import{m as r}from"./courses-BgYBHu8a.js";function u(e){const t=`manifest-${e.number}`;return{schemaVersion:2,revision:1,id:t,courseId:"manifest",locale:"fr",title:e.title,goal:e.goal,minutes:{learning:5,suggestedAction:5,review:2},direction:{hook:e.hook,reason:{id:`${t}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:["Mon objectif ; moins répéter","Agir, puis préparer davantage","Soutien avant de réessayer"]},why:{id:`${t}-purpose`,label:"Pourquoi cette action compte-t-elle dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:"Garde l’objectif. Choisis l’action utile.",instructions:e.instructions,prompts:[],suggestions:{action:e.action,minimum:e.minimum,cue:e.cue,place:e.place,fallback:e.fallback,observation:e.observation,minutes:[5,2,10],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:e.action[0],minimum:e.minimum[0],minutes:5,cueHint:e.cue[0],placeHint:e.place[0],obstacleHint:e.obstacle,fallbackHint:e.fallback[0],observationHint:e.observation[0]},accessibleAlternative:"Écris, dicte ou décris le rituel ; tu n’as besoin ni de matériel ni d’images mentales précises.",stopRule:e.stopRule},result:{question:"As-tu fait le minimum que tu avais choisi ?",observationPrompt:"Qu’as-tu fait concrètement, en dehors du rituel lui-même ?"},judgment:{primary:{id:`${t}-decision`,scenario:e.scenario,question:e.question,options:e.options.map(n=>({id:`${t}-${n.key}`,text:n.text,feedback:n.feedback})),bestOptionId:`${t}-${e.best}`}},carry:{takeaway:e.takeaway,followUp:{questionId:`${t}-return`,question:e.review,observationPrompt:"Que s’est-il passé au moment prévu, y compris les éventuelles réponses d’autres personnes ?",adjustmentPrompt:"Quel changement conviendrait à ta prochaine occasion d’agir ?"}},goDeeper:{sections:e.deeper,sourceIds:e.sources}}}const s=[{id:"manifest-T01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 effets indépendants issus de 21 articles, 15 907 participants : associer contraste mental et plans « si… alors… » a favorisé, en moyenne, l’atteinte des objectifs, g = 0,336 [0,229 ; 0,443]. Après correction du biais, l’estimation était de 0,242 [0,143 ; 0,342].",limitation:"Les effets variaient et des signes de biais de publication ont été relevés. Aucun résultat garanti, aucune preuve que l’inconfort soit nécessaire. Cette bibliothèque et ses adaptations des rituels n’ont pas été testées."},{id:"manifest-T02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Cette méta-analyse de référence regroupait 94 tests indépendants et 8 461 participants. Les plans précis « si… alors… » ont favorisé, en moyenne, l’atteinte des objectifs, d = 0,65 [0,60 ; 0,70].",limitation:"Les données sont anciennes, hétérogènes et pas toutes préenregistrées. Un plan ne supprime ni les obstacles extérieurs ni l’effort nécessaire, et ne garantit pas la décision d’une autre personne."},{id:"manifest-T03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 expériences randomisées, 19 951 participants au total : encourager le suivi des progrès a favorisé, en moyenne, l’atteinte des objectifs, d = 0,40 [0,32 ; 0,48]. Les études où les progrès étaient notés présentaient des effets plus grands.",limitation:"Les interventions et les objectifs variaient. Les comparaisons entre études ne prouvent pas l’efficacité de chaque fonction de suivi. Le bilan du lendemain est une adaptation ODA, pas un rythme optimal établi."},{id:"manifest-T04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 études, 123 effets, 5 685 participants : la simulation mentale a favorisé, en moyenne, les comportements ultérieurs, g = 0,49 [0,37 ; 0,62]. La comparaison globale n’a pas établi de différences entre les types de simulation.",limitation:"Les participants étaient surtout étudiants ; les tâches et simulations variaient. Plusieurs sous-groupes comptaient peu d’effets. Aucun classement fiable des types de simulation, aucune attraction d’événements extérieurs ni aucun avantage propre au coucher n’ont été établis."},{id:"manifest-T05",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Quatre expériences ont montré que certaines rêveries sur un avenir positif idéalisé réduisaient l’énergie immédiate, avec certaines différences dans les réalisations ultérieures. Elles distinguent la rêverie agréable de la préparation à l’effort.",limitation:"Des expériences courtes, surtout auprès d’étudiants. Cela ne montre pas que toute forme d’optimisme ou d’imagination soit nocive. Le supposé signal cérébral indiquant qu’un objectif est déjà atteint n’a pas été mesuré."},{id:"manifest-T06",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/abs/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Deux expériences ont montré que répéter une phrase très positive sur soi pouvait détériorer l’humeur des participants ayant une faible estime d’eux-mêmes. Les bénéfices étaient limités chez ceux ayant une forte estime d’eux-mêmes.",limitation:"Les phrases, échantillons et résultats à court terme étaient spécifiques. Cela ne montre pas que tout encouragement nuit, ni ne teste toutes les pratiques d’affirmation. Une phrase crédible liée à l’action est une adaptation ODA."},{id:"manifest-T07",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://pubmed.ncbi.nlm.nih.gov/25133846/",type:"research",finding:"144 tests expérimentaux portaient sur l’affirmation de valeurs, qualités ou relations importantes, associée à des informations de santé. Les effets sur l’acceptation et les intentions étaient faibles ; 46 tests comportementaux, 2 715 participants, donnaient d = 0,32 [0,19 ; 0,44].",limitation:"Affirmer ses valeurs diffère de répéter un résultat souhaité comme un fait. Les recherches sur les messages de santé n’établissent pas que des slogans répétés attirent un emploi, de l’argent ou une relation."},{id:"manifest-T08",title:"Carrillo et al. · 2019 · Best possible self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 études, 2 909 participants : écrire sur le meilleur avenir possible après avoir travaillé pour y parvenir a amélioré, en moyenne, le bien-être, l’optimisme et les émotions positives par rapport aux groupes témoins.",limitation:"Les participants étaient surtout de jeunes étudiants ; aucune étude ne remplissait tous les critères de qualité. Les résultats sur l’humeur et l’optimisme ne prouvent ni l’atteinte d’objectifs extérieurs ni l’efficacité du scripting au présent."},{id:"manifest-T09",title:"Davis et al. · 2016 · Gratitude interventions meta-analysis",url:"https://scottbarrykaufman.com/wp-content/uploads/2021/05/davis2016.pdf",type:"research",finding:"Les études randomisées sur la gratitude ont montré de faibles bénéfices moyens pour le bien-être face à certains groupes témoins. La gratitude ne faisait pas mieux que d’autres activités psychologiques actives pour le bien-être ; les résultats sur l’anxiété étaient non concluants.",limitation:"Les effets dépendent des activités de comparaison et de la qualité des études. Rien n’établit une fréquence universelle d’écriture, l’attraction d’événements extérieurs ou un effet supplémentaire en remerciant comme si un événement futur avait eu lieu."},{id:"manifest-T10",title:"Cregg & Cheavens · 2021, online 2020 · Gratitude and symptom change",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 études, 3 675 participants : les interventions de gratitude avaient de faibles effets moyens sur les symptômes de dépression et d’anxiété regroupés, plus grands face à une liste d’attente qu’à des activités témoins actives. L’analyse séparée de l’anxiété, avec cinq études, était non concluante.",limitation:"Ces effets modestes sur les symptômes ne font pas de la gratitude un traitement suffisant. Les auteurs recommandent des interventions mieux étayées aux personnes cherchant à soulager une dépression ou de l’anxiété."},{id:"manifest-T11",title:"Locke & Latham · 2002 · Goal setting and task motivation",url:"https://med.stanford.edu/content/dam/sm/s-spire/documents/PD.locke-and-latham-retrospective_Paper.pdf",type:"research",finding:"Cette synthèse de plusieurs décennies de recherche décrit comment des objectifs précis et exigeants peuvent soutenir la performance. L’engagement, les retours, les capacités et la complexité de la tâche influencent les résultats.",limitation:"Une revue théorique narrative, pas un test des rituels de manifestation. Les objectifs demandent des stratégies et des moyens accessibles. Pour une tâche nouvelle ou complexe, viser l’apprentissage peut convenir mieux que la performance immédiate."},{id:"manifest-T12",title:"Frattaroli · 2006 · Expressive disclosure meta-analysis",url:"https://bpb-us-e2.wpmucdn.com/faculty.sites.uci.edu/dist/c/602/files/2019/08/Frattaroli-psych-bulletin-2006.pdf",type:"research",finding:"146 études randomisées sur l’expression d’expériences ou d’émotions ont trouvé un faible bénéfice moyen, tous résultats confondus, r moyen = 0,075 [0,052 ; 0,098]. Les effets variaient selon les résultats mesurés et la procédure.",limitation:"Écrire sur des expériences réelles diffère de raconter un souhait comme un fait. Cette revue ne valide pas tous les journaux, ne promet pas de surmonter un traumatisme et ne montre pas que les récits écrits causent des résultats extérieurs."},{id:"manifest-T13",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Manifestation beliefs",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Trois échantillons d’enquêtes américaines en ligne, 1 023 participants : la croyance en la manifestation était corrélée à la confiance et à certains risques financiers et faillites déclarés, mais pas aux revenus ni au niveau d’études déclarés.",limitation:"Ces associations et résultats autodéclarés n’établissent ni causalité, ni prévalence dans la population, ni efficacité de chaque technique. La confiance n’est pas une preuve objective de réussite."},{id:"manifest-T14",title:"Denrell · 2003 · Undersampling failure and success stories",url:"https://pubsonline.informs.org/doi/10.1287/orsc.14.2.227.15164",type:"research",finding:"Cette analyse de l’apprentissage à partir d’organisations qui ont survécu montre qu’une pratique sans lien causal peut sembler associée à la réussite lorsque les échecs sont sous-représentés.",limitation:"Des modèles d’organisations, pas une étude de la publication virale décrite par le porteur du projet. Appliquer ce principe aux témoignages de manifestation est une inférence ; cela ne montre pas qu’une personne précise raconte une histoire malhonnête."},{id:"manifest-T15",title:"Awh, Belopolsky & Theeuwes · 2012 · Attentional control",url:"https://research.vu.nl/en/publications/top-down-versus-bottom-up-attentional-control-a-failed-theoretica/",type:"research",finding:"Cette revue sur l’attention décrit une sélection influencée par les objectifs actuels, ce qui attire visuellement l’attention et les sélections passées. Un objectif peut orienter l’attention, parmi d’autres influences.",limitation:"La théorie de l’attention visuelle ne teste ni les tableaux de visualisation, ni les affirmations, ni un filtre unique du SRA pour les souhaits, ni la création d’occasions extérieures. Repérer une occasion et la faire exister sont deux choses différentes."},{id:"manifest-T16",title:"Dai et al. · 2023 · Behavioral priming meta-analysis",url:"https://socialactionlab.org/wp-content/uploads/2024/01/Dai_Priming-Behavior-A-Meta-Analysis-of-the-Effects-of-Behavioral-and-Nonbehavioral-Primes-on-Overt-Behavioral-Outcomes_2023.pdf",type:"research",finding:"351 études, 862 effets : cette revue a trouvé un effet moyen de l’amorçage sur le comportement. Dans le sous-ensemble plus petit d’études préenregistrées, les effets étaient plus faibles et statistiquement non concluants, ce qui souligne l’incertitude sur leur fiabilité et leurs conditions.",limitation:"Les amorces incidentes des expériences diffèrent des rituels volontaires de manifestation. Le petit sous-ensemble préenregistré ne réfute pas tout amorçage ; le résultat global ne valide ni les phrases répétées, ni les seuils temporels précis, ni l’attraction cosmique."},{id:"manifest-T17",title:"Pham & Taylor · 1999 · Process versus outcome simulation",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167299025002010",type:"research",finding:"Une ancienne étude sur un examen favorisait la simulation du travail de révision plutôt que la seule bonne note imaginée. La planification et l’anxiété contribuaient à expliquer les différences de notes. L’effet principal du processus sur les notes était marginal ; une comparaison post hoc processus seul contre résultat seul était significative.",limitation:"La comparaison processus contre groupe témoin n’était pas significative dans la synthèse ultérieure de Cole, qui n’a établi aucun type universellement supérieur. Cette étude limitée ne montre ni gains fiables de notes face au groupe témoin ni attraction d’événements extérieurs."},{id:"manifest-T18",title:"Taylor et al. · 1998 · Mental simulation and self-regulation",url:"https://pubmed.ncbi.nlm.nih.gov/9572006/",type:"research",finding:"Cette présentation d’un programme de recherche distingue le fait d’imaginer le processus et la façon de surmonter les difficultés du fait d’imaginer seulement la réussite finale. Elle met l’accent sur la planification et la résolution de problèmes.",limitation:"Une revue d’un programme de recherche, pas une méta-analyse complète ni une preuve que l’imagerie du processus est toujours supérieure. À lire avec la synthèse ultérieure de Cole et à associer à un essai concret."},{id:"manifest-T19",title:"Larson-Prior, Ju & Galvin · 2014 · Sleep, wakefulness and arousal circuits",url:"https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2014.00165/full",type:"research",finding:"Cette revue en neurosciences décrit le système réticulaire activateur au sein de circuits qui interagissent pour réguler l’éveil et l’activation corticale.",limitation:"Les neurosciences de l’éveil n’établissent pas qu’écrire un souhait programme un filtre cérébral pour apporter des occasions, ni que la somnolence permet aux pensées de modifier les événements extérieurs. Aucun rituel de manifestation n’a été testé."},{id:"manifest-P01",title:"Taylor McGrath · 369 manifestation method",url:"https://www.theselfcollective.com.au/blogs/news/369-manifestation-method",type:"technique",finding:"Recette décrite par une praticienne : écrire une intention au présent trois fois le matin, six fois l’après-midi et neuf fois le soir.",limitation:"Un guide de pratique, pas des preuves contrôlées d’efficacité. Les nombres, cycles, effets annoncés sur l’attention et liens avec Tesla ne sont pas des résultats scientifiques."},{id:"manifest-P02",title:"Victoria Jackson · Scripting an ideal day",url:"https://themanifestationcollective.co/scripting-to-manifest/",type:"technique",finding:"Recette décrite par une praticienne : raconter une journée idéale imaginée à la première personne et au présent, ajouter des détails sensoriels et des émotions, puis relire.",limitation:"Décrit un rituel. La programmation du subconscient, les vibrations, les synchronicités et les résultats personnels ne sont pas des preuves issues de recherches contrôlées."},{id:"manifest-P03",title:"Jack Canfield · Creating a vision board",url:"https://jackcanfield.com/blog/vision-board/",type:"technique",finding:"Recette décrite par un praticien : choisir des objectifs et des images ou mots qui les représentent, composer un collage papier ou numérique, l’exposer et le consulter régulièrement.",limitation:"Un guide descriptif, pas des preuves d’efficacité des tableaux. Cette page n’établit ni la loi de l’attraction, ni la cause des réussites racontées, ni les explications faisant appel au SRA."},{id:"manifest-P04",title:"Jack Canfield · Daily affirmations",url:"https://jackcanfield.com/blog/daily-affirmations/",type:"technique",finding:"Recette décrite par un praticien : créer des phrases brèves et précises à la première personne, au présent, puis les lire ou les répéter, souvent matin et soir.",limitation:"Les phrases positives diffèrent des recherches sur l’affirmation de ses valeurs. Ce guide n’établit ni bénéfice universel ni effet sur des résultats extérieurs."},{id:"manifest-P05",title:"Jack Canfield · Visualization techniques",url:"https://jackcanfield.com/blog/visualization-techniques-manifest-your-dreams/",type:"technique",finding:"Ce guide décrit l’imagerie du résultat souhaité avec des détails sensoriels, la répétition mentale à la première personne et l’imagerie du processus pour atteindre un objectif.",limitation:"Des conseils descriptifs qui n’étayent ni garanties ni attraction. Les résultats empiriques sur la simulation doivent être vérifiés dans les sources de recherche."},{id:"manifest-P06",title:"Zanna Keithley · 55x5 method description",url:"https://zannakeithley.com/55x5-manifestation-method-worksheet/",type:"technique",finding:"Recette décrite par une praticienne : écrire une affirmation 55 fois de suite pendant cinq jours consécutifs, en imaginant qu’elle est déjà vraie.",limitation:"Une description publique ; aucun achat de fiche nécessaire. Les nombres de répétitions et les explications par de hautes vibrations ne sont pas des preuves établies d’efficacité."},{id:"manifest-P07",title:"Practitioner account · Two-cup method",url:"https://www.reddit.com/r/Manifestation/comments/1poqa0q/insanely_powerful_technique/",type:"technique",finding:"Recette racontée par une personne qui la pratique : étiqueter deux verres avec la situation actuelle et la situation souhaitée, imaginer le changement, verser l’eau du premier dans le second, puis boire.",limitation:"Un récit anonyme de pratique, pas des preuves causales vérifiées. Changer de réalité ou forcer un résultat sont des affirmations non étayées. Utilise de l’eau potable sans ajout et des verres propres."},{id:"manifest-P08",title:"Sandy · Pillow method guide",url:"https://theprettythoughts.com/the-pillow-method-an-easy-way-to-manifest/",type:"technique",finding:"Recette décrite par une praticienne : écrire un souhait au présent, plier le papier et le glisser sous l’oreiller, puis le répéter ou l’imaginer en s’endormant.",limitation:"Le nombre de répétitions et les pliages varient. Les affirmations sur le papier, le subconscient, les cristaux, les huiles et l’attraction ne sont pas des preuves contrôlées d’efficacité."},{id:"manifest-P09",title:"Sandy · Whisper method guide",url:"https://theprettythoughts.com/the-viral-whisper-method-manifestation-technique/",type:"technique",finding:"Recette décrite par une praticienne : se détendre, s’imaginer près d’une autre personne, lui murmurer une demande souhaitée à l’oreille trois fois, puis quitter la scène imaginée.",limitation:"Un témoignage personnel, pas des preuves de télépathie. Une demande imaginée ne permet pas de contrôler une autre personne ni de passer outre son consentement ou ses limites."},{id:"manifest-P10",title:"Simi · The Gratitude Game",url:"https://www.thesecret.tv/stories/the-gratitude-game/",type:"technique",finding:"Ce récit personnel décrit un journal de gratitude : noter ce qu’on apprécie avec les raisons de cette appréciation, puis relire.",limitation:"Un récit personnel, pas une recherche sur une intervention. L’histoire n’établit pas que la gratitude attire des événements ou élimine les problèmes."},{id:"manifest-P11",title:"Alexandra · Act as if it is already done",url:"https://www.thesecret.tv/stories/act-as-if-its-already-done/",type:"technique",finding:"Ce récit personnel décrit la préparation de vêtements et de bagages comme si un emploi souhaité était confirmé, en imaginant le résultat espéré.",limitation:"L’autrice rapporte une offre faite par une connaissance. Une anecdote ne permet pas d’isoler la cause ni de confirmer une loi générale de l’attraction."},{id:"manifest-P12",title:"Victoria Jackson · Letter from your future self",url:"https://themanifestationcollective.co/wp-content/uploads/2021/04/Scripting-To-Success-Masterclass.pdf",type:"technique",finding:"Cette ressource de pratique décrit une lettre où une version future imaginée de soi raconte les changements de sa vie à son soi actuel et lui témoigne de la compassion.",limitation:"Les pages 6-7 documentent la pratique, pas une communication avec le futur ni une efficacité sur les résultats extérieurs. La date et la formule d’ouverture sont des choix de présentation facultatifs."},{id:"manifest-P13",title:"Abraham / Esther and Jerry Hicks · 17-second focus",url:"https://spiritlibrary.com/abraham-hicks/only-17-seconds-away-from-your-true-desires",type:"technique",finding:"La transcription de cet enseignement invite à garder une pensée souhaitée pendant 17 secondes sans contradiction. Une variante en quatre intervalles totalise 68 secondes.",limitation:"Un enseignement spirituel, pas des preuves contrôlées. Les seuils précis, la combustion des pensées, leur manifestation physique et l’équivalence annoncée en heures de travail ne sont pas étayés."},{id:"manifest-P14",title:"Amy Parker · Creating a manifestation box",url:"https://envibelife.com/creating-a-manifestation-box/",type:"technique",finding:"Recette racontée par une praticienne : mettre des cartes d’intention ou des images dans une boîte, y inclure les émotions souhaitées, puis revenir consulter son contenu.",limitation:"Documente une pratique symbolique. Les explications par un champ d’énergie et la manifestation sont des croyances, pas des résultats scientifiques. Un contenant que tu possèdes suffit."},{id:"manifest-P15",title:"Neville Goddard · Five Lessons, 1948",url:"https://readnevillegoddard.com/five-lessons/",type:"technique",finding:"Ce texte original d’un enseignant décrit une détente proche du sommeil, une courte scène où le souhait est accompli, vécue à la première personne, puis répétée jusqu’à ce que l’action imaginée semble réelle.",limitation:"La transcription gratuite documente l’enseignement SATS, pas son efficacité. Les affirmations métaphysiques sur les résultats extérieurs ou l’absence d’action nécessaire ne sont pas des preuves scientifiques ; préserve ton sommeil."}],o=[{number:6,technique:"Méthode 3-6-9",title:"3-6-9 : fais une place aux candidatures",goal:"Garde le carnet, accomplis une étape vers ton objectif précis.",hook:"Encore « J’ai le poste » ? Candidate à l’entreprise sur l’autre page.",reason:"Ce carnet aide-t-il ta recherche d’emploi ou grignote-t-il ton temps pour candidater ?",paragraphs:["La méthode 3-6-9 : écris une affirmation au présent trois fois le matin, six à midi, neuf le soir. Variante à deux pages : entreprises visées à gauche, « J’ai le poste » à droite. Non étayé : ces nombres attireraient une offre. Un témoignage de réussite ne distingue pas répétitions et candidatures et laisse les échecs invisibles.","Version ODA : garde les pages ; le rythme reste facultatif. À gauche : entreprises visées et candidature, relance ou préparation du jour. À droite : une phrase crédible sur toi, un obstacle et un plan « si… alors… ». Ces plans précis ont un appui scientifique. Agis aujourd’hui ; demain, examine ton action et toute réponse séparément."],example:{title:"Camille utilise les deux pages",text:"Camille note deux entreprises de logistique à gauche et « Je prépare des candidatures utiles » à droite. Après déjeuner, elle consulte une offre et envoie un CV adapté. Son plan : « Si le site bloque, garder le brouillon et contacter le recrutement. » Un site bloque. Elle note sa demande de contact ; aucune entreprise n’a encore proposé de poste."},instructions:["Page gauche : note une entreprise et la candidature, relance ou préparation du jour.","Page droite : ajoute une phrase sur toi et un plan « si… alors… » face à l’obstacle.","Accomplis l’action prévue ; demain, examine ton essai et les réponses reçues."],action:["Envoyer une candidature adaptée","Relancer une entreprise"],minimum:["Envoyer une candidature pertinente","Envoyer une question de relance"],cue:["À la fin du déjeuner","Après mon écriture du matin"],place:["À mon bureau pour candidater","Sur le site de recrutement"],obstacle:"Le site de candidature ne charge pas",fallback:["Garder le brouillon et contacter le recrutement","Utiliser un autre moyen de candidater disponible"],observation:["Envoi ou demande, puis réponse éventuelle","L’étape de candidature accomplie"],stopRule:"Laisse les répétitions si elles prennent le temps d’agir ; suspends les candidatures trop coûteuses ou inadaptées.",scenario:"Camille a écrit ses 18 répétitions et listé trois entreprises. Une offre adaptée ferme ce soir. Pour candidater, il manque un court paragraphe sur son expérience.",question:"Que devrait produire sa prochaine séance avec le carnet ?",options:[{key:"repeat",text:"Garder le rythme des affirmations et développer sa phrase sur elle avant de reprendre la candidature.",feedback:"Cette phrase peut garder sa place dans le rituel, mais l’allonger ne complète pas la candidature. L’échéance approche : utilise le carnet pour lancer la rédaction du paragraphe demandé."},{key:"submit",text:"Écrire le paragraphe demandé, envoyer sa candidature et noter l’envoi séparément de toute réponse de l’employeur.",feedback:"Ce choix répond à l’objectif précis et à l’échéance. Elle maîtrise l’envoi, pas la réponse. Elle peut garder le rituel si elle l’aime, puis examiner ce qui s’est passé."},{key:"expand",text:"Allonger d’abord sa liste d’entreprises pour explorer demain un choix plus large de postes possibles.",feedback:"Élargir la recherche pourra servir plus tard. Ce soir, une offre adaptée a une échéance concrète. Allonger la liste retarderait cette candidature disponible. Termine d’abord le paragraphe manquant."}],best:"submit",takeaway:"Le carnet te rappelle de candidater. Compte actions et réponses séparément.",review:"Quelle action vers ton objectif as-tu tentée ? Une entreprise a-t-elle répondu ?",deeper:[{heading:"La recette habituelle, avec ses deux pages",paragraphs:["1. Choisis un résultat souhaité et formule-le comme déjà acquis. 2. Écris cette affirmation trois fois le matin. 3. Répète-la six fois vers midi. 4. Écris-la neuf fois le soir. Ces nombres décrivent la recette populaire, pas une dose validée par la recherche. La durée de cette routine varie selon les praticiens. [manifest-P01]","5. Dans l’exemple à deux pages transmis à ODA, la page droite dit « J’ai le poste » ; la gauche liste les entreprises où la créatrice a candidaté et qu’elle vise. Elle rapporte une offre d’une entreprise listée. Ce récit fourni par le porteur du projet n’est pas une donnée d’essai vérifiée indépendamment. Y appliquer le biais du survivant est une déduction : la réussite visible omet ceux qui ont essayé sans offre. Le récit peut être sincère sans éclaircir la cause. [manifest-T14]"]},{heading:"Garde le rythme, change ce qu’il déclenche",paragraphs:["Les données sur la planification concernent une situation reconnaissable associée à une réponse réalisable. Elles n’établissent pas que trois, six ou neuf répétitions influencent l’employeur. Garde le compte si tu l’apprécies et ajoute la tâche : une entreprise, une offre adaptée, l’action du jour. La liste de gauche et les candidatures offrent un chemin concret vers un poste ; l’anecdote ne prouve pas ce qui a causé cette offre. [manifest-T02, manifest-T14]","À droite, essaie « Je prépare des candidatures utiles ». Ajoute « Si le site bloque, je garderai le brouillon et contacterai le recrutement ». Vérifie l’échéance, l’accès et ton temps disponible. Envoie ou demande aujourd’hui, puis note l’action exacte. Demain, regarde la réponse sans attribuer le silence à un manque de conviction. Répétitions, préparation, candidatures et offres restent des entrées distinctes. Cette formule à deux pages est une adaptation ODA, pas une intervention testée. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Écriture d’un futur imaginé",title:"Futur imaginé : écris aussi ce qu’il te demande",goal:"Utilise une scène future pour choisir et tenter une action vers ton objectif.",hook:"Encore une journée idéale sur papier. Qu’as-tu fait avant le petit-déjeuner pour t’en rapprocher ?",reason:"Que feras-tu grâce à cette page, avant la suivante ?",paragraphs:["Le scripting est une page de journal écrite comme si l’avenir souhaité se déroulait maintenant. Choisis une scène, décris détails et émotions, puis relis-la. Résultats mitigés : l’écriture du « meilleur soi possible », proche de cette pratique, a amélioré en moyenne bien-être et optimisme ; elle n’établit pas que l’écriture au présent fait arriver les événements. L’écriture expressive porte sur des expériences vécues, pas des souhaits devenus faits.","Version ODA : garde la scène, ajoute le travail nécessaire. Nomme ton objectif précis, un obstacle actuel et une réponse « si… alors… ». Souligne une action à tenter aujourd’hui. Demain, compare l’essai au plan, pas à la scène entière. Cet exercice combiné reste une adaptation."],example:{title:"Élodie ajoute le travail manquant",text:"Élodie imagine une matinée calme dans un nouveau poste, après sa préparation d’entretien. Après dîner, elle enregistre une réponse sur la gestion d’un client difficile. Elle s’entend accélérer et repère une phrase à raccourcir. Le poste reste hypothétique ; l’enregistrement est réel, à réécouter et améliorer demain."},instructions:["Écris la scène future, avec le travail et les ressources nécessaires.","Souligne l’action du jour ; ajoute « Si cet obstacle apparaît, alors je… »","Tente le minimum et examine demain ce qui s’est passé."],action:["Enregistrer une réponse d’entretien","Rédiger une légende de portfolio"],minimum:["Garder un enregistrement de réponse","Garder une légende utilisable"],cue:["Après avoir débarrassé le dîner","Quand je ferme mon journal"],place:["À ma table de cuisine","Dans mon document de portfolio"],obstacle:"Je cherche la première phrase parfaite",fallback:["Commencer par une phrase provisoire","Demander un exemple précis"],observation:["L’enregistrement que j’ai gardé","Le brouillon et ce qui manque"],stopRule:"Évite les scènes qui te font souffrir ; prends de simples notes si imaginer l’avenir ne t’aide pas.",scenario:"Élodie décrit un entretien où elle est à l’aise. L’entretien est demain, et elle n’a aucun exemple pour une question courante sur la relation client.",question:"Quelle retouche rendrait sa page utile ce soir ?",options:[{key:"draft",text:"Ajouter un exemple client vécu, répéter une réponse et garder un premier enregistrement à revoir demain.",feedback:"Cela relie la scène à la tâche de demain. Une réponse provisoire révèle ce qu’il faut travailler. Elle n’assure pas le poste, mais fournit une préparation à examiner et améliorer."},{key:"feelings",text:"Décrire plus précisément la sensation de confiance avant de choisir l’exemple client qui convient.",feedback:"Explorer les émotions peut donner du sens à la scène. Ici, il manque une réponse fondée sur le vécu. Détailler les émotions ne comble pas ce manque ; choisis un exemple et répète-le."},{key:"edit",text:"Retravailler toute la page de journal pour que l’entretien imaginé suive un récit clair et cohérent.",feedback:"Un récit cohérent est un objectif d’écriture. Élodie doit surtout préparer une réponse. Retoucher l’histoire prend le peu de temps de sa soirée sans produire l’exemple nécessaire à l’entretien."}],best:"draft",takeaway:"Écris l’avenir que tu veux construire, puis fais aujourd’hui une part du travail.",review:"Quelle étape imaginée as-tu vraiment tentée ? Que reste-t-il à terminer ?",deeper:[{heading:"Comment se pratique le scripting",paragraphs:["1. Choisis une situation souhaitée, comme une journée dans le poste visé. 2. Écris une page de journal comme si elle se déroulait déjà. 3. Décris les détails ordinaires : où tu es, tes actions, tes émotions. 4. Relis-la et reprends-la si tu veux. Certaines variantes ajoutent gratitude ou certitude. Ce sont des consignes de praticiens, pas un chemin validé vers une offre. [manifest-P02]","Garde les événements imaginés clairement désignés comme tels. Tu peux décrire une scène ordinaire sans inventer une promesse d’autrui. Pour ODA, ajoute le travail nécessaire, les ressources disponibles et un obstacle actuel. Choisis une seule tâche sur cette page. Saisir ou dicter le texte facilite l’accès ; nous ne prétendons pas que tous les formats ont les mêmes effets étudiés. Le rituel reste facultatif. [manifest-P02]"]},{heading:"Imaginer l’avenir et écrire le vécu diffèrent",paragraphs:["Les recherches sur le « meilleur soi possible » demandent d’imaginer un bel avenir après avoir travaillé pour lui. Carrillo et ses collègues ont trouvé des bénéfices moyens sur le bien-être, l’optimisme et les émotions positives, avec des limites de qualité des études. Cela permet une attente mesurée envers l’écriture réflexive. Rien n’établit que le scripting au présent produit les événements écrits. L’écriture expressive porte sur le vécu ou les émotions. Son petit bénéfice moyen ne valide pas non plus l’attraction d’événements futurs. [manifest-T08, manifest-T12]","ODA garde le récit et lui donne un débouché concret. Choisis un objectif précis de ton essai en cours. Nomme ce qui pourrait bloquer l’étape du jour, puis écris une réponse à ta portée. Enregistre une occasion et un minimum, essaie, puis reviens demain. Note une répétition d’entretien comme préparation, une candidature comme envoi, et une réponse seulement à son arrivée. Ce parcours est une adaptation conçue par ODA, pas l’une des interventions d’écriture initialement testées."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Tableau de visualisation",title:"Tableau de visualisation : une image, une action",goal:"Utilise une image du tableau pour commencer une action réalisable.",hook:"Ce bureau du tableau te plaît. Que feras-tu au tien aujourd’hui ?",reason:"Cette image montre-t-elle ta priorité ou la réussite selon les autres ?",paragraphs:["Un tableau de visualisation rassemble images et mots de la vie souhaitée. Choisis, dispose et affiche les images, puis reviens les regarder. Résultats mitigés : les objectifs actuels, ce qui attire l’œil et l’expérience passée peuvent orienter l’attention. Cela n’établit ni l’efficacité du tableau ni l’attraction d’occasions par les images. Le système réticulaire activateur concerne l’éveil ; le « filtre à souhaits programmable » dépasse les données.","Version ODA : garde une image qui compte. Ajoute son objectif précis et l’action du jour. Nomme un obstacle et une réponse « si… alors… » ; sers-toi de l’image pour commencer. Demain, vérifie si ce repère t’a mené au minimum. Repérer une occasion n’est pas la créer."],example:{title:"Nora annote le bureau",text:"Nora annote une image de bureau en studio de design : « Créer un exemple pour mon portfolio ». En voyant l’image après le petit-déjeuner, elle ouvre son projet inachevé et écrit une légende. Moins excitant que son rêve de studio, mais elle l’enregistre et note qu’un avis reste nécessaire."},instructions:["Choisis une image ; ajoute son objectif précis et l’action utile du jour.","Que sa vue déclenche l’action ; prévois une réponse à un obstacle probable.","Tente l’action et vérifie demain si tu as remarqué ce repère."],action:["Écrire une légende de portfolio","Demander un avis sur un projet"],minimum:["Garder une légende de projet utilisable","Envoyer une question précise pour un avis"],cue:["Quand je vois le tableau après le petit-déjeuner","Quand j’ouvre mon dossier de projet"],place:["À mon bureau de travail","Dans mon document de portfolio"],obstacle:"L’image me fait naviguer au lieu de travailler",fallback:["Ouvrir le projet avant de naviguer","Mettre un rappel écrit près du fichier"],observation:["Si l’image m’a fait commencer","La légende ou demande terminée"],stopRule:"Utilise les images ou mots disponibles ; évite les images qui te poussent à dépenser.",scenario:"Nora voit son tableau chaque matin, puis regarde des photos de studios. Il manque à son portfolio la légende qui expliquerait un projet terminé.",question:"Quel changement serait le plus utile ?",options:[{key:"fresh",text:"Remplacer l’image du studio par une plus inspirante pour redonner de l’intérêt au tableau.",feedback:"Une nouvelle image peut faire plaisir. Mais ses notes montrent qu’elle navigue après ce repère, pas qu’elle manque d’envie. Change l’action que la vue de cette image lui rappelle."},{key:"study",text:"Comparer demain matin des portfolios de studios pour comprendre le niveau qu’elle souhaite atteindre.",feedback:"Comparer peut éclairer le travail futur. Nora a déjà un projet terminé à légender. Naviguer encore répéterait le même schéma, sauf pour répondre à une question nécessaire à cette légende."},{key:"label",text:"Écrire sur l’image « Ouvrir le projet, écrire la légende », puis en garder une avant toute photo de studio.",feedback:"Cela relie le repère existant à l’action manquante. Demain, Nora pourra vérifier si elle a vu l’annotation et gardé la légende. Le tableau lui-même ne garantit aucun poste en studio."}],best:"label",takeaway:"Donne à l’image une tâche à lancer. Examine cette tâche, pas le pouvoir de l’image.",review:"Voir ton image t’a-t-il mené à l’action enregistrée, ou à autre chose ?",deeper:[{heading:"Crée ton tableau sans rien acheter",paragraphs:["1. Choisis une direction ou situation souhaitée. 2. Rassemble quelques images et mots qui la représentent. 3. Dispose-les sur papier, un tableau existant ou une page numérique. 4. Place cet ensemble là où tu comptes le revoir. 5. Regarde-le en imaginant la situation souhaitée. Ces étapes décrivent l’exercice des praticiens ; elles ne prouvent pas qu’un tableau fait exister cette situation. [manifest-P03]","Pour ce cours, garde une direction au lieu d’empiler tous les changements de vie possibles. Une photo existante, un croquis ou un mot suffit. Sous une image, nomme la vraie tâche : poser une question sur une formation, finir un exemple ou envoyer une candidature adaptée. Choisis un endroit où agir quand tu vois l’image. Matériaux et disposition dépendent de tes préférences ; aucune exigence scientifique n’impose d’acheter du matériel spécial. Sépare la mise en page des images et la tâche accomplie."]},{heading:"Ce que remarquer permet ou non d’expliquer",paragraphs:["La recherche décrit une attention influencée par les objectifs actuels, ce qui ressort visuellement et les sélections passées. Chercher volontairement des occasions pertinentes paraît donc plausible ; cela ne valide pas toute méthode proposée pour mieux les repérer. Le système réticulaire activateur participe aux circuits d’éveil et de vigilance. Ces résultats n’établissent pas un filtre commandé par le tableau qui apporte travail, partenaire ou maison. Une occasion nouvellement repérée pouvait exister avant que tu y prêtes attention. [manifest-T15, manifest-T19]","ODA fait de l’image un rappel explicite sans lui attribuer de mécanisme caché. Écris l’objectif, l’action du jour et une réponse à l’obstacle le plus probable. Si voir le tableau lance une séance de navigation, prévois d’ouvrir d’abord ton fichier de travail. Demain, vérifie si le repère s’est présenté, si tu l’as remarqué et ce que tu as fait. Garde les réponses extérieures à part. Cette formule associant image et plan n’a pas été testée comme intervention par tableau de visualisation."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Affirmations",title:"Affirmations : choisis une phrase qui t’aide à agir",goal:"Associe une phrase encourageante à une action observable vers ton objectif.",hook:"« Je réussis tout » sonne faux ? Essaie une phrase qui t’aide à agir.",reason:"Cette phrase t’aide-t-elle à agir ou t’impose-t-elle d’y croire ?",paragraphs:["Les affirmations sont des phrases encourageantes répétées, à l’oral ou à l’écrit, souvent comme si le résultat était acquis. Choisis une phrase, répète-la et imagine y croire. Résultats mitigés : Wood et ses collègues ont observé qu’une phrase très positive dégradait l’humeur de certains participants à faible estime de soi. L’auto-affirmation étudiée porte souvent sur les valeurs importantes, pas des slogans ; les résultats sur les comportements de santé n’établissent pas l’attraction d’un emploi.","Version ODA : choisis une phrase utilisable, une valeur et l’action qui l’exprime : « Je prépare un exemple honnête. » Précise l’objectif, l’obstacle et une réponse « si… alors… ». Essaie aujourd’hui, examine l’action demain. Remplace ou laisse toute phrase qui dégrade ton humeur."],example:{title:"Léa change de phrase",text:"Avant une réunion, Léa répète « Je suis une excellente oratrice » et se sent plus gênée. Elle choisit « Je prépare une idée claire », écrit une suggestion à son bureau et la répète. En réunion, elle dit la première phrase, puis perd le fil. Elle note sa contribution et l’explication inachevée."},instructions:["Choisis une phrase encourageante liée à une valeur et une action précise.","Nomme un obstacle ; ajoute une réponse « si… alors… » faisable, sans exiger d’y croire.","Tente l’action aujourd’hui ; demain, examine l’acte et l’effet de la phrase sur toi."],action:["Dire une phrase préparée en réunion","Poser une question claire sur le projet"],minimum:["Dire la première phrase de ma suggestion","Envoyer une question précise sur le projet"],cue:["Quand la réunion accueille les suggestions","Quand j’ouvre le fil du projet"],place:["Dans notre salle de réunion","Dans le fil de discussion du projet"],obstacle:"Ma phrase encourageante sonne faux",fallback:["Dire la phrase préparée sans affirmation","Passer à un simple rappel de l’action"],observation:["Mes paroles et la réponse reçue","Si la phrase aide ou me pèse"],stopRule:"Remplace ou laisse les phrases qui te font souffrir ; aucune certitude forcée n’est nécessaire.",scenario:"L’affirmation de réussite répétée par Léa la fait se sentir moins bien. Elle veut proposer une idée utile en réunion et a une première phrase prête.",question:"Quel ajustement tient compte des deux faits ?",options:[{key:"persist",text:"Garder l’affirmation de réussite quelques séances de plus avant de la changer, en répétant aussi sa suggestion.",feedback:"Répéter peut aider la préparation. Mais rien n’impose de conserver une phrase qui dégrade son humeur. Sa suggestion prête lui offre un autre départ sans l’obliger à croire l’affirmation."},{key:"action",text:"Utiliser un simple rappel ou laisser l’affirmation, puis dire sa phrase quand la réunion accueille les suggestions.",feedback:"Cela garde une contribution faisable tout en tenant compte de l’inconfort signalé. Léa peut examiner ses paroles et l’effet du rappel. Aucune certitude d’être une excellente oratrice n’est nécessaire."},{key:"wait",text:"Préparer une affirmation plus forte sur ses qualités et reporter sa suggestion jusqu’à se sentir plus convaincue.",feedback:"Réfléchir à ses valeurs diffère de se convaincre d’une grande affirmation. Attendre cette conviction impose la confiance comme préalable à une action prête. Garde une petite contribution et la phrase facultative."}],best:"action",takeaway:"La phrase peut te rappeler d’agir. L’action apporte des éléments concrets.",review:"Qu’as-tu tenté ? La phrase t’a-t-elle aidé, gêné, ou n’a-t-elle rien changé ?",deeper:[{heading:"La pratique populaire des affirmations",paragraphs:["1. Choisis un résultat ou une qualité personnelle. 2. Formule-le positivement, souvent au présent. 3. Dis-le ou écris-le à répétition. 4. Imagine la situation souhaitée en utilisant cette phrase. 5. Reprends-la au moment choisi. Fréquence et formulation varient selon les praticiens ; la recette habituelle n’établit ni nombre de répétitions ni ressenti scientifiquement requis. [manifest-P04]","Tu peux apprécier la pratique sans reprendre sa plus grande promesse. Pour ODA, choisis une phrase orientée vers un travail à ta portée. « Je prépare une idée claire » peut accompagner tes notes de réunion. Tu peux aussi te passer de phrase. Une affirmation gênante ou peu crédible n’est pas une épreuve obligatoire. Wood et ses collègues ont étudié une phrase positive précise et l’humeur à court terme ; leur résultat ne montre pas que toute phrase bienveillante nuit. [manifest-T06]"]},{heading:"Une valeur diffère d’un slogan de réussite",paragraphs:["Dans les recherches sur l’auto-affirmation, les participants réfléchissent souvent à leurs valeurs, qualités ou relations importantes avant de recevoir des informations potentiellement menaçantes. Epton et ses collègues ont regroupé des expériences sur des messages de santé : petits effets moyens sur l’acceptation et les intentions, avec un bénéfice comportemental dans ce cadre. Ces démarches diffèrent de répéter un résultat souhaité comme acquis. Elles n’établissent pas qu’une offre d’emploi suit la phrase « J’ai le poste ». [manifest-T07]","ODA reprend cette distinction sans prétendre que tout le rituel est testé. Choisis une valeur, comme l’honnêteté, et une façon de l’exprimer dans ton objectif : préparer un exemple exact de ton travail. Enregistre l’occasion et le minimum. Prévois une réponse à un obstacle probable, comme perdre le fil, puis essaie la phrase aujourd’hui. Demain, note ta contribution réelle et si la phrase était utilisable. Laisse l’affirmation si elle ajoute de la pression ; garde l’action faisable. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Visualisation",title:"Visualisation : répète l’action dans la scène",goal:"Entraîne-toi à une tâche avec un obstacle, puis tente-la.",hook:"L’offre te fait rêver, mais une question te bloque ? Entraîne-toi à répondre.",reason:"Une autre scène montre-t-elle ce qui manque, ou retarde-t-elle l’action prête ?",paragraphs:["Visualiser consiste à imaginer un événement souhaité, avec souvent des détails sensoriels et un sentiment de réussite. Installe-toi, imagine la scène, participe mentalement et recommence si tu veux. Résultats mitigés pour la manifestation : la simulation mentale a favorisé en moyenne le comportement ultérieur, sans établir l’attraction d’événements. Une ancienne étude avant un examen favorisait l’imagerie du processus dans certaines comparaisons ; la méta-analyse ultérieure n’a trouvé aucun type supérieur de façon fiable.","Version ODA : garde une brève scène du résultat, puis répète la tâche face à un obstacle. Précise l’objectif et une réponse « si… alors… ». Essaie aujourd’hui, reviens demain. Répéter reste une préparation. Sans images, écris les étapes ; aucune image nette ni ressenti particulier n’est requis."],example:{title:"Benoît répète la question difficile",text:"Benoît imagine finir un entretien, puis répète l’explication d’une période sans emploi. S’il bloque, il commencera par les dates. Après déjeuner, il s’enregistre et remarque qu’il omet ce qu’il a appris. Il ajoute une phrase. La réponse demande encore de l’entraînement ; aucun résultat d’entretien n’existe encore."},instructions:["Garde une brève scène du résultat ; répète la prochaine tâche et une difficulté probable.","Écris un objectif précis et une réponse « si… alors… » à cette difficulté.","Tente la vraie action aujourd’hui ; demain, examine-la séparément de la répétition."],action:["Enregistrer une réponse d’entraînement à l’entretien","Envoyer une suggestion de réunion préparée"],minimum:["Garder un premier enregistrement de réponse","Envoyer une phrase de suggestion"],cue:["À la fin du déjeuner","Quand on demande des idées en réunion"],place:["À mon bureau de préparation d’entretien","Dans le fil de discussion d’équipe"],obstacle:"Je bloque dès la première phrase",fallback:["Commencer par les dates de mes notes","Lire la courte introduction préparée"],observation:["La réponse que j’ai enregistrée","Préparation et contribution réelle, notées séparément"],stopRule:"Arrête les images qui augmentent ta détresse ; utilise de simples notes et une occasion en journée.",scenario:"Benoît a imaginé deux fois un entretien réussi. Son enregistrement évite toujours d’expliquer la période sans emploi. Il reste cinq minutes avant son départ.",question:"Comment utiliser l’imagerie face à ce manque ?",options:[{key:"rehearse",text:"Répéter la première phrase sur cette période, enregistrer une réponse provisoire et vérifier les dates nécessaires.",feedback:"La préparation cible ainsi le manque constaté et produit un enregistrement à examiner. L’imagerie n’assure pas le résultat de l’entretien. Ici, elle sert à aider Benoît à tenter sa réponse."},{key:"outcome",text:"Reprendre la scène d’entretien réussi avec davantage de détails, puis noter la confiance qu’elle lui donne.",feedback:"La confiance peut être une observation, mais elle ne répond pas à la question manquante. Son enregistrement révèle une explication précise à travailler. Utilise le temps restant pour la répéter et l’enregistrer."},{key:"research",text:"Comparer plusieurs méthodes de visualisation pendant ce temps avant de choisir laquelle pratiquer ce soir.",feedback:"Comparer peut être intéressant, mais rien ici n’impose un type d’imagerie avant de commencer. Benoît connaît déjà la tâche manquante. Un court essai donne des informations plus pertinentes qu’une recherche de méthode."}],best:"rehearse",takeaway:"Repère une tâche dans la scène. Répéter prépare ; essayer met à l’épreuve.",review:"Qu’as-tu tenté après la répétition ? Quel manque est devenu visible ?",deeper:[{heading:"La scène habituelle du résultat souhaité",paragraphs:["1. Choisis un événement souhaité. 2. Installe-toi confortablement. 3. Imagine une courte scène montrant le résultat voulu. 4. Imagine y participer, avec des détails qui comptent pour toi. 5. Reprends la scène si tu veux. Certains praticiens demandent une émotion forte ou l’impression d’avoir déjà le résultat. Ces consignes décrivent un rituel ; elles n’établissent pas que sa scène attire un événement extérieur. [manifest-P05]","Pour ODA, garde la scène assez courte pour laisser du temps au travail. Identifie la prochaine tâche entre aujourd’hui et cette scène. Répète mentalement une difficulté de cette tâche, puis écris la réponse à tenter. Sans images précises, tu peux décrire les étapes. C’est une option d’accessibilité, pas une preuve d’effets identiques entre tous les formats de préparation. Ne note jamais une réponse imaginée de l’employeur comme réelle."]},{heading:"Aucun type d’imagerie ne gagne partout",paragraphs:["L’étude initiale de Pham et Taylor comparait l’imagerie du travail de révision, celle de la note souhaitée, des combinaisons et un groupe témoin. Certaines comparaisons favorisaient le processus ; le résultat sur les notes ne justifie pas un bénéfice fiable face au témoin. Cole et ses collègues ont ensuite regroupé diverses simulations mentales : bénéfice comportemental moyen, sans différence établie entre les types. Plusieurs sous-groupes étaient petits. Promettre qu’une scène marche toujours mieux dépasserait ces données. [manifest-T17, manifest-T04]","ODA te demande quelle préparation ta tâche exige. Si tu connais l’objectif mais évites la première phrase, répète le départ et la réponse à cet obstacle. Enregistre un minimum faisable, un déclencheur, un lieu et une réponse. Essaie aujourd’hui, reviens demain. Note séparément la répétition utile et la tâche réelle. Si la préparation continue sans essai, raccourcis-la ou choisis une autre occasion disponible. Cette séquence de la scène à l’essai est une adaptation ODA, pas un protocole validé par la méta-analyse."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]}],l=[{number:11,technique:"Méthode 55x5",title:"55x5 : ton carnet est plein, ta candidature attend",goal:"Associe l’écriture facultative à une action faisable, puis fais le point.",hook:"55 lignes écrites, candidature vide ? Écris la prochaine phrase utile au dossier.",reason:"Combien de temps peux-tu écrire sans sacrifier la tâche utile ?",paragraphs:["La méthode 55x5 : écris une affirmation au présent 55 fois par jour pendant cinq jours. Choisis ton but ; recopie la phrase jusqu’au nombre prévu. Non étayé : ce nombre ou ces cinq jours attireraient un résultat. Dans certaines expériences, des rêveries idéalisées ont réduit l’énergie immédiate, sans prouver que toute imagination ou ce rituel nuit à l’effort.","Version ODA : écris si ça te plaît, sans répétitions obligatoires. Choisis un objectif précis et une action faisable chaque jour. Prévois quoi faire si l’obstacle survient, avec un déclencheur reconnaissable. Agis aujourd’hui avant d’écrire davantage ; examine la tâche demain. La recherche soutient les plans précis, pas ce calendrier de répétitions."],example:{title:"Thomas garde du temps pour candidater",text:"Thomas recopie volontiers « Je prépare des candidatures utiles », mais ses 55 lignes prennent toute sa pause. Il en garde quelques-unes et réserve cinq minutes après déjeuner pour candidater. S’il manque une information, il la demande au recrutement. Il envoie sa question aujourd’hui et la note séparément d’une candidature ou d’une offre."},instructions:["Choisis un objectif ; réserve du temps pour agir avant de fixer les répétitions.","Choisis un déclencheur reconnaissable et prévois quoi faire face à un obstacle.","Essaie la tâche aujourd’hui, puis fais le point demain ; répéter reste facultatif."],action:["Demander une information manquante","Compléter une rubrique de candidature"],minimum:["Envoyer une question au recrutement","Enregistrer une rubrique complète"],cue:["À la fin du déjeuner","Après ma séance d’écriture facultative"],place:["Dans mon brouillon au recrutement","À mon bureau pour candidater"],obstacle:"Les répétitions prennent tout mon temps disponible",fallback:["Passer les répétitions et faire le minimum","Réserver un créneau d’action avant d’ouvrir le carnet"],observation:["Tâche faite et temps d’écriture séparés","Ce que j’ai envoyé ou enregistré"],stopRule:"Réduis ou supprime l’écriture si elle te fatigue ou prend le temps disponible pour agir.",scenario:"Thomas a terminé deux jours de 55 répétitions. Aucun ne lui a laissé de temps pour sa candidature. Il dispose aujourd’hui de la même courte pause.",question:"Quel changement permet de tester une routine plus utile ?",options:[{key:"faster",text:"Recopier plus vite pour conserver le rituel complet et peut-être commencer la candidature ensuite.",feedback:"Écrire plus vite peut encore laisser la candidature de côté. Ses notes montrent le conflit entre les deux activités. Réserve d’abord un créneau réaliste pour la tâche, puis vois combien de temps reste pour l’écriture facultative."},{key:"weekend",text:"Terminer les cinq jours d’écriture, puis consacrer une séance plus longue à la candidature ce week-end.",feedback:"Une séance ce week-end serait peut-être possible, mais elle reporte la tâche pour préserver un nombre sans fondement établi. Une petite occasion existe aujourd’hui. Essaie d’en profiter avant d’ajouter des répétitions."},{key:"reserve",text:"Réserver cinq minutes à une rubrique, réduire ou supprimer les répétitions, puis revoir la rubrique enregistrée demain.",feedback:"Cela change ce qui empêchait d’avancer. L’écriture reste un choix, et travailler sur la candidature devient faisable. Une rubrique enregistrée prépare l’envoi du dossier ; elle ne constitue pas une offre d’emploi."}],best:"reserve",takeaway:"Garde du temps pour agir. Finir les répétitions n’est pas accomplir la tâche.",review:"Quelle tâche as-tu essayée, et combien de temps l’écriture t’a-t-elle laissé pour elle ?",deeper:[{heading:"Les cinq jours de répétition habituels",paragraphs:["1. Choisis un résultat souhaité. 2. Écris une phrase positive comme s’il s’était déjà produit. 3. Recopie-la 55 fois lors d’une séance quotidienne. 4. Recommence pendant cinq jours. 5. Pense au résultat souhaité en écrivant. Le compte exact vient des consignes de praticiens, pas d’une dose établie par la recherche contrôlée. Certaines variantes demandent aussi de ressentir des émotions ou de rester concentré sans interruption. [manifest-P06]","Garde ce format d’écriture s’il te plaît, mais regarde le temps qu’il prend. Avant de commencer, fixe le temps nécessaire pour avancer aujourd’hui vers ton objectif. La version ODA permet une séance plus courte ou aucune répétition. Manquer un jour n’annule pas un résultat futur. Une page remplie compte comme de l’écriture ; une rubrique de candidature enregistrée compte comme du travail sur le dossier. Aucune des deux ne signifie qu’un employeur a fait une offre."]},{heading:"Répéter n’est pas planifier",paragraphs:["La méta-analyse de Gollwitzer et Sheeran soutient les plans qui associent une situation précise à une action vers un objectif, pour des tâches variées. Elle ne teste ni 55 répétitions ni une règle de manifestation sur cinq jours. Kappes et Oettingen ont observé que certaines rêveries positives idéalisées réduisaient l’énergie immédiate. Ces brèves expériences invitent à ne pas remplacer la préparation par un résultat agréable imaginé. Elles ne prouvent pas que toute pensée optimiste ou phrase répétée est nuisible. [manifest-T02, manifest-T05]","ODA utilise la page pour un plan pratique. Nomme ton objectif, la plus petite tâche utile et le moment où tu peux la faire. Si l’écriture remplit souvent la pause, prévois d’agir d’abord. Si une information manque pour compléter une rubrique, pose la question précise. Essaie aujourd’hui, puis fais le point demain : le déclencheur s’est-il présenté, quelle tâche as-tu faite, que reste-t-il ? Cette organisation de l’écriture et de l’action est une adaptation, sans résultat promis en cinq jours."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"Méthode des deux verres",title:"Deux verres : ton portfolio attend toujours",goal:"Utilise les étiquettes pour choisir une action faisable et prévoir un obstacle.",hook:"Verser l’eau est facile. Quelle action te rapproche du but ?",reason:"Comment rendre la situation souhaitée possible avec ton temps et tes moyens ?",paragraphs:["Sur deux verres, inscris la situation actuelle et celle souhaitée. Remplis le premier, imagine le changement, verse dans le second et bois l’eau. Non étayé : l’eau porterait une intention ou permettrait un changement de dimension. Les recherches concernent les objectifs précis, les stratégies et les retours, pas une explication quantique du versement.","Version ODA : garde les verres symboliques, ou dessine deux cercles. Entre les étiquettes, écris un objectif précis, un obstacle réel et un plan « si… alors… ». WOOP associe souhait, résultat, obstacle et plan ; cette combinaison aide en moyenne selon la recherche. Essaie aujourd’hui une action vers le but. Demain, distingue tes actions des résultats extérieurs."],example:{title:"Malik écrit ce qui manque",text:"Malik étiquette ses verres « Portfolio inachevé » et « Prêt à candidater ». Entre eux, il note : « Enregistrer une légende après déjeuner ». S’il peine à expliquer le projet, il décrira la décision principale. Il verse l’eau, puis écrit la légende. Le portfolio attend encore un projet ; la note montre ce qui a changé."},instructions:["Étiquette la situation actuelle et l’objectif souhaité ; garde un changement faisable.","Entre les deux, écris l’action du jour et un plan « si… alors… » face à l’obstacle.","Essaie cette action ; demain, reviens sur le travail réellement fait."],action:["Écrire une légende de projet","Demander un prérequis de formation"],minimum:["Enregistrer une légende expliquant une décision","Envoyer une question sur la formation"],cue:["À la fin du déjeuner","Quand je range les verres"],place:["Dans mon document de portfolio","À la table de la cuisine"],obstacle:"La situation souhaitée exige plus de moyens",fallback:["Demander un accès ou une solution plus simple","Décrire simplement une décision du projet"],observation:["La tâche que j’ai vraiment faite","Ce qui sépare encore les étiquettes"],stopRule:"Dessine si tu préfères ; si tu choisis de boire, utilise uniquement de l’eau potable.",scenario:"Le verre souhaité de Malik indique « Prêt à candidater ». Son portfolio comporte un projet terminé sans légende, et un second encore inachevé.",question:"Quelle action convient à cinq minutes disponibles ?",options:[{key:"caption",text:"Écrire et enregistrer la légende du projet terminé, puis noter ce qui empêche encore le portfolio d’être prêt.",feedback:"La tâche est faisable et laisse visible ce qui manque. Une légende ne termine pas tout le portfolio, mais elle apporte un progrès concret à examiner lors du prochain bilan."},{key:"rename",text:"Remplacer l’étiquette souhaitée par « Designer embauché » pour garder l’ambition globale visible pendant le rituel.",feedback:"L’ambition globale peut compter, mais changer l’étiquette ne complète pas le portfolio. Garde cette aspiration et choisis la petite tâche que permettent les cinq minutes disponibles."},{key:"schedule",text:"Lister toutes les tâches restantes du portfolio avant d’écrire la légende, pour prévoir le parcours complet.",feedback:"La liste pourra aider lors d’un prochain bilan. Pour ce court créneau, la légende manquante est déjà identifiée. La terminer permet de tester une action faisable, sans consacrer tout le temps à préparer davantage."}],best:"caption",takeaway:"Les étiquettes montrent l’écart. Une action à ta portée peut en combler une partie.",review:"Qu’a changé ton action, et qu’est-ce qui sépare encore tes deux étiquettes ?",deeper:[{heading:"Le rituel habituel des deux verres",paragraphs:["1. Prends deux verres et inscris ta situation actuelle sur le premier. 2. Inscris la situation souhaitée sur le second. 3. Mets de l’eau dans le premier verre. 4. Imagine le changement souhaité en versant dans le second. 5. Bois l’eau et repense à la situation souhaitée. Certains praticiens parlent de saut entre dimensions. Les éléments examinés n’établissent pas cette explication métaphysique. [manifest-P07]","Tu peux garder le transfert symbolique sans tenir son explication pour un fait. Des verres déjà disponibles ou deux cercles dessinés suffisent pour ODA. Écris une action entre les étiquettes avant de verser. N’inscris pas comme acquise une décision incertaine qui dépend d’autrui. Écrire une légende utile relève de toi ; être embauché implique un employeur. Si tu bois, utilise uniquement de l’eau potable. Aucun récipient spécial ni achat n’est nécessaire."]},{heading:"WOOP : vérifier comment avancer",paragraphs:["WOOP organise un souhait, le résultat espéré, l’obstacle actuel et un plan. La méta-analyse du contraste mental associé aux plans « si… alors… » a montré un bénéfice moyen modeste pour atteindre les objectifs, avec des variations et des signes de biais de publication. Elle n’a testé ni verres ni eau. La théorie des objectifs prend aussi en compte l’engagement, les retours, les capacités et la complexité de la tâche. Une étiquette porteuse de sens exige un chemin praticable ; un objectif difficile sans accès ni stratégie ne suffit pas. [manifest-T01, manifest-T11]","ODA précise comment avancer. Choisis une tâche pour ton objectif actuel. Nomme un obstacle auquel tu peux répondre et vérifie les contraintes extérieures : matériel ou argent manquants, par exemple. « Si je ne peux pas accéder à l’outil, je demanderai une alternative disponible » peut faire d’une demande d’aide ton action. Enregistre le minimum et le déclencheur, essaie aujourd’hui, puis fais le point demain. Distingue les demandes de l’aide reçue. Les verres symboliques associés à ces étapes pratiques restent une adaptation, pas une méthode combinée testée."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:15,technique:"Journal de gratitude",title:"Gratitude : tu peux remercier et être déçu",goal:"Note ce que tu apprécies vraiment et agis sans effacer la difficulté.",hook:"Candidature refusée malgré l’aide d’une amie ? Remercie-la sans cacher ta déception.",reason:"Qu’apprécies-tu sans devoir cacher ce qui doit changer ?",paragraphs:["Un journal de gratitude note ce que tu apprécies, souvent avec raisons et relecture. Des variantes remercient pour un événement futur comme s’il était arrivé. Résultats mitigés : ces exercices améliorent légèrement le bien-être en moyenne face à certains témoins, mais dépassent peu les alternatives psychologiques actives. Les effets sur les symptômes sont modestes ; la gratitude ne suffit pas comme traitement et ne prouve pas l’attraction d’événements futurs.","Version ODA : décris un fait dans ton journal. Nomme l’objectif précis, une difficulté et ce que tu apprécies. Prévois quoi faire face à un obstacle et une action aujourd’hui : remercier ou demander un avis ciblé. Demain, examine l’action et la réponse éventuelle. Tu peux rester reconnaissant sans cacher ta déception."],example:{title:"Inès garde les deux faits",text:"Inès apprécie la relecture de son amie, mais note aussi le refus. Après le petit-déjeuner, elle demande quelle phrase d’introduction retravailler. Sans appel possible, elle enverra un message court. L’amie ne peut répondre aujourd’hui. Inès note sa question et sa déception, sans inventer un retour."},instructions:["Note une chose réellement appréciée et pourquoi ; laisse la difficulté visible.","Nomme l’action utile du jour et prévois quoi faire face à un obstacle probable.","Essaie cette action ; demain, reviens sur elle et la réponse éventuelle."],action:["Demander un retour ciblé","Remercier pour une aide précise"],minimum:["Envoyer une question sur ma candidature","Envoyer un remerciement précis"],cue:["À la fin du petit-déjeuner","Quand je termine ma note de gratitude"],place:["Dans ma conversation par messages","À la table de la cuisine"],obstacle:"La personne qui m’aide ne peut pas appeler",fallback:["Envoyer une seule question concise","Choisir une autre personne disponible pour relire"],observation:["Demande envoyée et réponse reçue","Gratitude et difficulté notées honnêtement"],stopRule:"Ne force pas la gratitude ; une détresse persistante mérite un soutien au-delà du journal.",scenario:"Inès apprécie le soutien d’une amie, mais le refus de sa candidature la peine. Son amie propose de répondre par message à une question ciblée.",question:"Quelle note et quelle action conviennent ?",options:[{key:"positive",text:"Noter seulement les moments de soutien du jour et reporter l’examen du refus jusqu’à ressentir plus de gratitude.",feedback:"Elle peut garder ce qu’elle apprécie dans sa note, sans reporter un problème concret. Son amie propose un retour : Inès peut poser une question utile tout en reconnaissant que le refus fait mal."},{key:"both",text:"Noter le soutien et la déception, puis demander quelle phrase d’introduction rendrait la prochaine candidature plus claire.",feedback:"La gratitude reste liée à un fait réel, et Inès utilise l’aide disponible. Le message est une demande, pas un avis reçu. Demain, elle pourra noter toute réponse et choisir une correction."},{key:"future",text:"Remercier pour la prochaine offre comme si elle était arrivée, puis relire avant de demander un avis.",feedback:"Cette version tournée vers l’avenir est un rituel de praticiens, pas l’exercice de gratitude testé dans les revues citées. Elle ne peut pas établir une offre. Une appréciation réelle et une question ciblée gardent la note ancrée dans les faits."}],best:"both",takeaway:"Apprécie ce qui est réel. Garde la difficulté et la prochaine action utile visibles.",review:"Qu’as-tu apprécié, quelle action as-tu essayée, et quelqu’un t’a-t-il répondu ?",deeper:[{heading:"Le journal de gratitude habituel",paragraphs:["1. Ouvre un carnet ou ton outil d’écriture habituel. 2. Nomme une chose que tu apprécies. 3. Décris pourquoi elle compte pour toi. 4. Ajoute un autre élément si tu veux. 5. Relis à un moment choisi. Un récit de praticienne décrit ce format avec raisons et relecture. Les variantes de manifestation peuvent remercier pour un événement futur souhaité. C’est une autre affirmation que d’apprécier une aide déjà reçue. [manifest-P10]","Pour ODA, un détail ordinaire suffit : une réponse utile, un outil partagé ou un moment de repos. Tu n’as pas à trouver du positif pour chaque problème. Si un refus, une difficulté d’accès ou une déception compte aujourd’hui, note-le à côté de ce que tu apprécies. Choisis une action utile pour ton objectif actuel. La note sert à réfléchir ; remercier ou envoyer une demande constitue un acte distinct. Ni l’écriture ni une demande ne garantissent une réponse."]},{heading:"De petits bénéfices, selon la comparaison",paragraphs:["Davis et ses collègues ont trouvé de petits bénéfices moyens de bien-être face à certains témoins. La gratitude ne surpassait pas les alternatives psychologiques actives pour le bien-être ; les résultats sur l’anxiété restaient peu concluants. Cregg et Cheavens ont trouvé des changements moyens modestes des symptômes de dépression et d’anxiété regroupés, plus grands face aux listes d’attente qu’aux témoins actifs. Leur analyse séparée de l’anxiété restait peu concluante. Ces résultats n’établissent ni une dose idéale de journal, ni un soulagement garanti, ni un traitement suffisant. Ils ne testent pas l’arrivée d’événements parce qu’on a remercié l’univers. [manifest-T09, manifest-T10]","ODA ajoute un plan pratique sans l’appeler l’intervention testée. Garde un objectif précis, nomme l’obstacle actuel et prévois quoi faire s’il survient. Si une personne aidante ne peut pas appeler, envoie plutôt une question ciblée. Essaie aujourd’hui, puis fais le point demain. Distingue la demande de toute réponse et laisse la déception dans tes notes. Tu peux passer la gratitude si elle te semble forcée, tout en faisant l’action utile ou en cherchant du soutien."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"Faire comme si / incarner un rôle",title:"Faire comme si : travaille avant d’acheter la tenue",goal:"Exprime le rôle souhaité par un comportement à ta portée.",hook:"Tu veux te sentir pro ? Prépare un exemple avant d’acheter la tenue.",reason:"Quel comportement exprime ton objectif sans prendre l’argent nécessaire ailleurs ?",paragraphs:["Faire comme si, ou incarner un rôle, c’est agir comme si le résultat était déjà acquis. Choisis l’identité, imagine ses habitudes, puis adopte un comportement ou un symbole. Résultats mitigés : objectifs précis et retours peuvent aider les performances ; prétendre le résultat acquis n’a aucun mécanisme d’attraction établi. Des enquêtes ont associé les croyances en la manifestation à certains risques financiers, sans établir de causalité.","Version ODA : garde le rôle ; choisis une action à ta portée que tu contrôles. Nomme l’objectif précis, l’obstacle et quoi faire s’il survient. Un professionnel peut préparer un exemple utile ou poser une question claire. Agis aujourd’hui et reviens dessus demain. Acheter des symboles reste facultatif ; l’accord d’autrui lui appartient."],example:{title:"Karim essaie le rôle",text:"Karim veut devenir analyste indépendant. Il envisage un fauteuil cher, puis choisit d’améliorer un exemple de tableur. Après déjeuner, il vérifie un calcul et l’explique. Si le logiciel est inaccessible, il utilisera un outil gratuit disponible. Son exemple est plus clair ; il n’a toujours aucun client."},instructions:["Nomme le rôle souhaité et un comportement précis, à ta portée, qui l’exprime.","Prévois quoi faire face à un obstacle ; ne promets pas les décisions d’autrui.","Essaie ce comportement aujourd’hui ; demain, examine tes actions et tes dépenses."],action:["Améliorer un exemple de travail","Poser une question ciblée au client"],minimum:["Enregistrer un calcul expliqué dans l’exemple","Envoyer une question pour préciser le projet"],cue:["À la fin du déjeuner","Quand j’ouvre le fichier exemple"],place:["À mon bureau de travail","Dans mon exemple de tableur"],obstacle:"Je n’ai pas accès à l’outil prévu",fallback:["Utiliser un outil gratuit disponible","Écrire l’explication dans un fichier texte"],observation:["Travail produit et argent vraiment dépensé","La modification enregistrée dans l’exemple"],stopRule:"Dépense selon tes moyens ; ne tiens pas pour acquis un revenu incertain ou le consentement d’autrui.",scenario:"Karim veut travailler en indépendant sans avoir de client confirmé. Un outil payant prendrait l’argent réservé aux besoins essentiels ; un outil gratuit disponible suffit pour son exemple.",question:"Quelle action exprime le mieux ce rôle aujourd’hui ?",options:[{key:"sample",text:"Améliorer un exemple avec l’outil disponible, noter le changement et préserver l’argent nécessaire aux besoins essentiels.",feedback:"Le rôle devient un comportement accessible, avec un résultat vérifiable. Cela ne garantit aucun client, mais améliore ce que Karim peut montrer. L’argent nécessaire au quotidien n’a pas à financer un symbole incertain."},{key:"purchase",text:"Acheter l’outil payant maintenant pour que son environnement corresponde à l’identité professionnelle qu’il souhaite incarner.",feedback:"Un outil peut servir quand la tâche l’exige et le budget le permet. Ici, l’outil gratuit suffit, tandis que l’achat menace les besoins essentiels. Essayer un rôle ne garantit pas un revenu futur."},{key:"wait",text:"Attendre un client confirmé avant de préparer un exemple, pour éviter d’investir des efforts dans un résultat incertain.",feedback:"Préserver son argent est raisonnable, mais les moyens disponibles permettent un petit exemple. Attendre la certitude bloque aussi cet essai accessible. Fixe une limite d’effort réaliste et regarde ce qu’il faut améliorer."}],best:"sample",takeaway:"Agis selon tes moyens. Distingue le rôle, les dépenses et les résultats extérieurs.",review:"Quel comportement as-tu essayé, à quel coût, et quel résultat connais-tu vraiment ?",deeper:[{heading:"L’essai habituel d’une identité",paragraphs:["1. Choisis la situation ou l’identité souhaitée. 2. Imagine comment cette personne passe une journée ordinaire. 3. Choisis des comportements, objets ou habitudes associés à cette vie. 4. Agis comme si le changement avait déjà eu lieu. 5. Observe ton ressenti et recommence si tu veux. Une praticienne raconte avoir préparé vêtements et bagages comme si un emploi était confirmé. L’offre reçue ensuite est une anecdote, pas une comparaison contrôlée. [manifest-P11]","ODA garde l’essai du rôle avec un comportement dont le coût reste prudent. Préparer un exemple de travail, venir avec un ordre du jour ou poser une question claire peut servir ton objectif actuel. Posséder des objets chers n’est pas nécessaire pour essayer le rôle. N’agis pas comme si quelqu’un avait donné son consentement ou un employeur t’avait embauché sans confirmation. Un avenir possible indique une direction, pas une ressource déjà disponible."]},{heading:"Les objectifs demandent des retours et des moyens",paragraphs:["La théorie des objectifs décrit comment des buts précis et exigeants peuvent aider les performances, en tenant compte de l’engagement, des retours, des capacités et de la complexité. Elle n’établit pas qu’adopter une identité produit à elle seule le résultat souhaité. Dixon et ses collègues ont trouvé des corrélations entre les croyances en la manifestation et certains risques financiers et faillites déclarés, sans établir de causalité. Se sentir confiant ou avoir l’impression de réussir n’équivaut pas à un revenu déjà reçu. [manifest-T11, manifest-T13]","ODA choisit un comportement avant un symbole. Nomme le résultat concret de la tâche du jour et le temps ou les outils disponibles. Prévois quoi faire face à un obstacle probable, comme un logiciel inaccessible, et garde un minimum à ta portée. Essaie aujourd’hui et fais le point demain. Note séparément le travail produit, son coût et toute réponse extérieure. Si un achat ou une promesse suppose un succès déjà acquis, revois ton parcours. Cette association du rôle et de l’action est une adaptation ; les études citées ne l’ont pas testée comme exercice d’incarnation."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Lettre de la personne que tu seras",title:"Lettre du futur : même les mardis difficiles",goal:"Ajoute à ta lettre du futur une action faisable cette semaine.",hook:"Mardi, tout presse ? Ta lettre du futur peut aussi raconter ces journées.",reason:"Quel avenir mérite une action faisable cette semaine ?",paragraphs:["Imagine-toi dans le futur, écrivant à la personne que tu es aujourd’hui. Choisis une date future, décris ta vie et les changements, encourage-toi, puis relis. Résultats mitigés : les recherches proches sur le meilleur soi possible soutiennent des bénéfices moyens de bien-être et d’optimisme, pas des messages du futur ni des objectifs garantis. L’exercice décrit aussi le travail pour construire cette vie.","Version ODA : garde cette voix, les efforts, l’aide et une journée ordinaire difficile. Nomme l’objectif précis, l’obstacle et quoi faire s’il survient. Enregistre l’action d’aujourd’hui et une occasion réaliste. La recherche soutient les plans précis ; cette combinaison reste une adaptation. Demain, examine ton essai, pas la réalisation d’une prédiction."],example:{title:"Camille écrit la journée ordinaire",text:"Dans sa lettre, Camille décrit une semaine plus stable et explique comment demander les priorités quand les tâches se heurtent. Aujourd’hui, en ouvrant sa messagerie professionnelle, elle envoie une question. Si sa responsable est indisponible, elle utilisera la conversation d’équipe. La réponse tarde. Elle note sa demande et une charge encore non résolue."},instructions:["Écris depuis ton avenir ; ajoute les efforts, l’aide et un obstacle ordinaire.","Choisis l’action du jour et un déclencheur précis ; prévois une réponse faisable à l’obstacle.","Essaie le minimum et reviens demain sur ce qui s’est réellement passé."],action:["Demander quelle tâche est prioritaire","Réserver un créneau d’entraînement réaliste"],minimum:["Envoyer une demande de précision","Confirmer un créneau d’entraînement disponible"],cue:["Quand j’ouvre ma messagerie professionnelle","Après avoir débarrassé le dîner"],place:["Dans la conversation d’équipe","À la table de la cuisine"],obstacle:"La personne nécessaire est indisponible",fallback:["Utiliser la conversation d’équipe convenue","Choisir un autre créneau d’entraînement disponible"],observation:["Demande envoyée et réponse reçue","Le créneau que j’ai réellement confirmé"],stopRule:"Choisis un avenir plus proche ou moins exigeant si la lettre met la pression ; tu peux faire une pause.",scenario:"La lettre du futur de Camille promet une semaine équilibrée. Aujourd’hui, deux tâches urgentes se heurtent. Sa responsable invite les questions de priorité dans la conversation d’équipe.",question:"Quel ajout mérite sa place dans la lettre ?",options:[{key:"calendar",text:"Décrire l’emploi du temps complet d’une semaine idéale avant de demander quelle urgence traiter d’abord aujourd’hui.",feedback:"Un emploi du temps peut guider les choix à venir, mais ne tranche pas seul ce conflit de priorités. Camille a un moyen de demander des précisions. Utilise-le et garde la question sans réponse visible."},{key:"certainty",text:"Renforcer les encouragements à faire confiance à l’avenir, puis attendre de se sentir moins débordée par le travail.",feedback:"Les encouragements peuvent aider, mais attendre un autre ressenti laisse les deux urgences en concurrence. Une demande courte est déjà faisable. La lettre devrait aider Camille à l’envoyer, sans prédire la réponse."},{key:"request",text:"Décrire comment demander les priorités les jours difficiles, puis envoyer une question dans la conversation d’équipe convenue.",feedback:"La scène future contient alors un comportement adapté à l’obstacle actuel. L’envoi dépend d’elle ; la réponse reste inconnue jusqu’à son arrivée. Demain, elle pourra revoir la demande et choisir la suite."}],best:"request",takeaway:"Dans ta lettre, précise le travail d’aujourd’hui et l’aide qu’il peut demander.",review:"Quelle étape as-tu essayée, et quelle aide ou quel résultat reste inconnu ?",deeper:[{heading:"Le format habituel de la lettre",paragraphs:["1. Choisis un moment futur de ta vie. 2. Imagine-toi à cette période. 3. Adresse une lettre à la personne que tu es aujourd’hui. 4. Décris les changements et ton quotidien. 5. Offre des encouragements ou conseils, puis relis. Une ressource de praticienne décrit cette voix du futur vers le présent et son approche bienveillante. Dates et salutations sont des choix de format, pas des ingrédients scientifiquement nécessaires. [manifest-P12]","Pour ODA, décris l’avenir souhaité sans prétendre recevoir un message ou une prédiction. Ajoute une difficulté ordinaire, les efforts nécessaires et l’aide dont tu pourrais avoir besoin. Une semaine plus calme peut demander de discuter des priorités plutôt que de croire plus fort à l’avenir. Relie cette direction à ton essai du cours. Souligne une action faisable pour la personne qui se réveillera demain avec les mêmes moyens réels. Tu peux écrire depuis un avenir proche si un avenir lointain te pèse."]},{heading:"Écrire l’espoir, puis revenir à aujourd’hui",paragraphs:["La méta-analyse du meilleur soi possible a trouvé des bénéfices moyens de bien-être, d’optimisme et d’émotions positives face aux témoins. Les participants étaient souvent de jeunes étudiants, et aucune étude ne remplissait tous les critères de qualité. L’avenir imaginé suit les efforts faits pour l’atteindre ; rien n’établit que les lettres prédisent ou produisent des événements extérieurs. Les recherches sur les intentions de mise en œuvre soutiennent séparément un déclencheur précis associé à une réponse faisable. Aucune de ces sources n’a testé cette combinaison exacte avec une lettre. [manifest-T08, manifest-T02]","ODA utilise la lettre pour choisir une action. Nomme un objectif précis, repère l’obstacle le plus proche de la tâche du jour et écris « Si cela arrive, je… » avec une réponse faisable. Enregistre le déclencheur, le lieu et le minimum, puis essaie aujourd’hui ou au prochain moment choisi. Demain, examine les faits : une demande, une tâche, un retard ou une pause. Si quelqu’un n’a pas répondu, garde la réponse inconnue. Ajuste la suite sans prendre l’avenir imaginé pour une preuve déjà acquise."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]}],c=[{number:13,technique:"Méthode de l’oreiller",title:"Méthode de l’oreiller : une note utile au réveil",goal:"Garde le mot du soir, avec une action au réveil.",hook:"Tu réécris ton souhait au lieu de dormir ? Garde le mot, avec une action pour demain.",reason:"Prévoir en journée me laisserait-il dormir ?",paragraphs:["La méthode de l’oreiller consiste à glisser un souhait écrit sous ton oreiller. Une version courante : l’écrire comme déjà réalisé, plier le papier, le placer dessous, puis répéter la phrase ou imaginer le résultat au coucher. Non étayé : l’idée que ce papier produise un résultat extérieur, d’après les données examinées. [manifest-P08, manifest-T19]","Version ODA : garde le mot, ajoute un objectif précis et un obstacle probable, puis un plan « si…, alors… » pour une action. La recherche soutient ces plans précis ; elle n’établit aucun pouvoir d’attraction propre au coucher. Fais un geste utile aujourd’hui, reviens dessus demain. Si prévoir t’empêche de dormir, réserve la suite à la journée. [manifest-T02, manifest-T19]"],example:{title:"Le message du matin",text:"Dans sa cuisine, Camille écrit son souhait d’emploi et envoie une candidature ciblée. Sur le mot : une fois le petit déjeuner débarrassé, consulter une nouvelle offre adaptée. Le lendemain, elle la consulte et commence une autre candidature. Il manque des détails. Ses notes distinguent l’envoi du brouillon inachevé. Aucun employeur n’a répondu."},instructions:["Garde le mot ; ajoute ton objectif et l’obstacle avant de te coucher.","Écris ton plan « si…, alors… » ; fais un geste utile aujourd’hui.","Demain, examine l’action tentée séparément du rituel de l’oreiller."],action:["Envoyer une candidature ciblée","Interroger un contact sur une offre"],minimum:["Déposer une candidature adaptée","Envoyer une question précise"],cue:["Après avoir débarrassé le petit déjeuner","Après ma pause déjeuner d’aujourd’hui"],place:["À la table de la cuisine","À mon poste habituel"],obstacle:"Prévoir au coucher me tient éveillé",fallback:["Prévoir à la pause déjeuner demain","Utiliser un mot en journée"],observation:["Candidature envoyée ; réponse inconnue","Question envoyée ; réponse notée séparément"],stopRule:"Arrête si le rituel retarde ton sommeil. Prévois en journée ; aucune répétition au coucher n’est nécessaire.",scenario:"Le mot de Camille prévoit une question matinale sur une offre adaptée. Le réécrire au coucher l’empêche de dormir, alors que le moment prévu demain est clair.",question:"Que devrait-elle faire ce soir ?",options:[{key:"a",text:"Réécrire encore le mot, puis décider demain si poser la question sur l’offre lui convient toujours.",feedback:"Réécrire lui coûte du sommeil sans apporter de précision nécessaire. Elle sait déjà quand agir. Qu’elle garde la question prévue et réserve les autres retouches à la journée."},{key:"b",text:"Laisser le mot, dormir et poser sa question au moment prévu après le réveil.",feedback:"Elle protège son sommeil et garde son engagement utile. Demain, elle pourra noter si elle a envoyé la question, en distinguant son action d’une éventuelle réponse de l’employeur."},{key:"c",text:"Remplacer le suivi du matin par une longue visualisation en journée de la réponse de l’employeur.",feedback:"La journée convient mieux pour prévoir longuement, mais elle remplacerait ici un geste utile possible. Imaginer une réponse n’envoie pas le message et ne révèle pas la décision de l’employeur."}],best:"b",takeaway:"Garde un mot bref sous l’oreiller et prévois quand agir après le réveil.",review:"Quelle action as-tu tentée après le mot ? Prévoir au coucher a-t-il gêné ton sommeil ?",deeper:[{heading:"La recette habituelle de l’oreiller",paragraphs:["1. Choisis un résultat souhaité et écris une phrase au présent, par exemple une offre d’emploi imaginée comme déjà reçue. C’est la recette d’une praticienne : la phrase exprime un souhait, pas une nouvelle vérifiée. Tu peux garder son contenu pour toi. [manifest-P08]","2. Plie le papier et glisse-le sous ton oreiller. Le guide ajoute des consignes d’écriture et de pliage propres à cette variante. Ce ne sont pas des conditions établies pour obtenir un résultat extérieur. Un papier ordinaire que tu as déjà suffit. [manifest-P08]","3. Lis ou répète mentalement la phrase en te couchant. Imagine le souhait réalisé si cette partie te plaît. Puis laisse venir le sommeil : ni une image nette, ni des répétitions, ni une sensation précise ne sont nécessaires pour arrêter. [manifest-P08]","4. Reprends le mot un autre soir si tu le souhaites. Le guide décrit un rituel reconnaissable, sans preuve d’efficacité contrôlée. Une revue des circuits de l’éveil n’établit pas que les souhaits au coucher contournent l’esprit critique ou provoquent des événements extérieurs. [manifest-P08, manifest-T19]"]},{heading:"Une note qui sert au réveil",paragraphs:["Avant de te coucher, ajoute une petite consigne pratique. Écris l’objectif précis, l’obstacle attendu et l’action que tu peux faire. Pour chercher un emploi : « Si le petit déjeuner est débarrassé, je déposerai une candidature adaptée. Si le formulaire me bloque, je poserai une question précise au recruteur. » Distingue l’action des résultats incertains, comme une offre. [manifest-T02]","La méta-analyse de Gollwitzer et Sheeran a trouvé un bénéfice moyen pour l’atteinte des objectifs avec des plans « si…, alors… » précis, dans des contextes variés. Elle n’a pas testé le papier sous l’oreiller, ni établi que prévoir supprime l’effort. La revue sur l’éveil décrit des circuits qui interagissent, pas une voie inconsciente réalisant les souhaits. Ces affirmations sont distinctes. [manifest-T02, manifest-T19]","ODA propose un essai aujourd’hui et un bilan demain : des choix pratiques, pas un ensemble validé pour le coucher. Note ce que tu as envoyé, demandé ou terminé ; les réponses se notent séparément. Si retoucher le mot te tient éveillé, laisse-le et choisis une occasion en journée. Ton prochain geste utile n’exige pas de finir le rituel. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Méthode du chuchotement",title:"Chuchotement : prépare une demande que tu peux faire",goal:"Fais de l’échange imaginé une demande respectueuse que tu peux vraiment faire.",hook:"Tu attends un message qui ne vient pas ? Le chuchotement peut t’aider à choisir ton prochain geste.",reason:"Puis-je faire une demande appropriée ?",paragraphs:["La méthode du chuchotement consiste à imaginer une demande à quelqu’un. Version courante : te détendre, imaginer l’approcher, chuchoter trois fois ce que tu souhaites, puis quitter la scène. Non étayé : provoquer sa réponse à distance, selon les données examinées. Son consentement et ses limites comptent toujours. [manifest-P09]","Version ODA : garde le chuchotement privé, choisis un objectif précis et nomme l’obstacle. Répète une demande respectueuse qui laisse place au refus. Écris un plan « si…, alors… » pour une action appropriée aujourd’hui ; reviens dessus demain. La recherche soutient ces plans. Te sentir certain de sa réponse ne prouve pas que l’autre acceptera. [manifest-T02, manifest-T13]"],example:{title:"Demander sans insister",text:"À midi, Julien imagine chuchoter une demande de réunion. Il en tire une phrase à envoyer : « On pourrait parler dix minutes jeudi ? » Sa collègue répond que jeudi est complet. Julien note le message et le refus, puis demande si la semaine suivante convient. Le rituel n’obligeait pas sa collègue à accepter."},instructions:["Chuchote ta demande en privé ; laisse à l’autre le choix de refuser.","Nomme l’objectif, l’obstacle et ton plan ; fais une demande appropriée aujourd’hui.","Demain, examine ta demande et la façon dont tu as respecté la réponse."],action:["Demander une courte réunion de projet","Envoyer une question appropriée sur les disponibilités"],minimum:["Envoyer une demande de réunion claire","Poser une question pertinente"],cue:["Après ma pause déjeuner d’aujourd’hui","Au début de notre point convenu"],place:["À mon bureau","Dans notre lieu de réunion habituel"],obstacle:"Je retouche sans cesse une demande simple",fallback:["Utiliser une demande en une phrase","Demander pendant le point convenu"],observation:["Demande faite ; réponse notée séparément","Limite respectée ; suite choisie"],stopRule:"Ne contacte pas une personne qui a refusé le contact. Imaginer en privé ne permet pas de passer outre ses limites.",scenario:"Julien souhaite une réunion. Sa collègue a dit que cette semaine est complète, mais l’a invité à demander pour la suivante. Son chuchotement le rassure.",question:"Quel geste correspond aux informations qu’il a ?",options:[{key:"a",text:"Demander une fois ses disponibilités la semaine suivante, puis accepter sa réponse sans multiplier les messages.",feedback:"Elle lui a proposé cette possibilité ; une question claire la respecte. Il peut noter séparément demande et réponse. Se sentir rassuré ne lui donne aucun droit sur son temps."},{key:"b",text:"Attendre qu’elle propose un horaire, car l’échange imaginé lui semble désormais terminé.",feedback:"Il peut choisir d’attendre, mais l’échange imaginé n’a pas posé la question. Son invitation lui donne une occasion appropriée de faire une vraie demande, si la réunion lui importe toujours."},{key:"c",text:"Envoyer une explication plus chaleureuse de l’importance qu’aurait pour lui une réunion cette semaine.",feedback:"Même chaleureux, ce message lui demanderait de revoir la semaine qu’elle a exclue. Qu’il utilise la possibilité proposée, sans faire de ses sentiments une raison pour insister auprès d’elle."}],best:"a",takeaway:"Prépare ta demande ; l’autre reste libre de sa réponse.",review:"Quelle demande as-tu faite ? Comment as-tu réagi à la réponse ou à la limite posée ?",deeper:[{heading:"L’échange imaginé dans la recette courante",paragraphs:["1. Choisis la personne et la réponse souhaitée. Dans le récit de la praticienne, l’exercice se déroule en imagination. Choisir une réponse exprime ton envie ; cela ne révèle ni ce que l’autre souhaite ni une autorisation de le contacter. [manifest-P09]","2. Détends-toi et imagine cette personne dans un lieu. Imagine l’approcher et lui chuchoter ta demande à l’oreille trois fois. Ce nombre appartient à la recette ; ce n’est pas une dose scientifique pour influencer quelqu’un. Tu peux adapter l’exercice, les yeux ouverts ou en mots. [manifest-P09]","3. Quitte la scène imaginée. Certaines variantes ajoutent un baiser imaginé sur le front : un détail de la scène, pas une preuve d’influence à distance. Avec ODA, garde l’exercice privé et choisis une demande respectueuse. Une intimité imaginée ne vaut pas consentement. [manifest-P09]","4. Décide si une vraie demande est appropriée. Le récit décrit le rituel, sans démontrer télépathie ou contrôle. Une personne peut refuser, se taire ou changer d’avis. Répéter des chuchotements ne crée aucune obligation de te répondre. [manifest-P09]"]},{heading:"Prévois ce qui dépend de toi",paragraphs:["Garde un objectif précis : demander une réunion possible diffère de vouloir susciter l’admiration. Nomme un obstacle auquel tu peux répondre, comme retoucher sans cesse un court message. Choisis ensuite quand agir : « Si ma pause déjeuner se termine, j’enverrai une question claire sur les disponibilités. » Si le contact est malvenu, ton action peut consister à respecter cette limite. [manifest-T02, manifest-P09]","La recherche sur les intentions d’implémentation soutient l’association d’une situation repérable à une réponse choisie. Elle n’établit pas de contrôle sur le destinataire. Dans trois échantillons d’enquêtes en ligne, Dixon et ses collègues ont associé la croyance en la manifestation à la confiance et à certains risques financiers déclarés. Ces liens n’établissent aucune causalité ; l’étude n’a pas testé le chuchotement. Ta certitude ne mesure pas l’accord de l’autre. [manifest-T02, manifest-T13]","La répétition privée et le retour du lendemain sont des adaptations ODA. Fais une demande appropriée aujourd’hui ou prévois une occasion convenue. Demain, note ce que tu as demandé, toute réponse reçue et si tu l’as respectée. Sans réponse, son avis reste inconnu. Choisis un autre geste approprié ou arrête ; ne compte pas l’échange imaginé comme une vraie conversation. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:18,technique:"Concentration de 17 secondes",title:"17 secondes : le minuteur donne le départ",goal:"Utilise une pause choisie pour agir, sans lui prêter un seuil scientifique.",hook:"Ton esprit vagabonde avant dix-sept secondes ? Tu peux quand même agir.",reason:"Le minuteur m’aide-t-il à agir ou me retarde-t-il ?",paragraphs:["La méthode des 17 secondes demande de garder une pensée souhaitée sans la contredire pendant dix-sept secondes. Certaines versions enchaînent quatre intervalles, soit soixante-huit secondes. Non étayé : ces durées précises et un seuil d’attraction, selon les données examinées. La recherche sur l’amorçage ne valide pas ces durées ou ces rituels volontaires de souhait. [manifest-P13, manifest-T16]","Version ODA : garde les dix-sept secondes comme pause choisie, puis nomme un objectif précis et un obstacle. Prévois une action aujourd’hui avec un plan « si…, alors… » ; examine ton essai demain. La recherche soutient ces plans précis. Une pensée vagabonde n’oblige pas à recommencer avant d’agir. Le minuteur donne le départ ; il n’est pas une condition de résultat. [manifest-T02, manifest-P13]"],example:{title:"La pause interrompue",text:"Avant déjeuner, Inès règle dix-sept secondes pour son portfolio. Une livraison interrompt sa pensée. Elle laisse le minuteur et suit son plan : après déjeuner, envoyer un exemple pertinent de son travail à un client. Celui-ci demande un autre style. Inès note le message et le retour sans recommencer l’exercice."},instructions:["Choisis ton objectif ; les dix-sept secondes de pause restent facultatives.","Nomme l’obstacle et prévois quoi faire ; agis utilement aujourd’hui.","Demain, examine l’action tentée et les retours éventuels reçus."],action:["Envoyer un exemple de travail pertinent","Demander un retour sur un brouillon"],minimum:["Envoyer un exemple adapté","Poser une question précise pour un retour"],cue:["Après mon déjeuner d’aujourd’hui","À la fin du minuteur facultatif"],place:["À mon poste habituel","À une table de la bibliothèque"],obstacle:"Je recommence dès que mon attention dérive",fallback:["Envoyer sans le minuteur","Utiliser un rappel écrit pour agir"],observation:["Exemple envoyé ; réponse notée séparément","Question posée ; retour inconnu"],stopRule:"Laisse le minuteur si recommencer retarde l’action ou te cause de la détresse. Aucune pensée indésirable n’exige de correction rituelle.",scenario:"L’exemple préparé par Inès correspond à la demande d’un client. Une notification a interrompu son minuteur. Elle a cinq minutes pour l’envoyer avant une réunion.",question:"Comment profiter au mieux de cette occasion ?",options:[{key:"a",text:"Recommencer une fois sans notifications, puis envoyer l’exemple s’il reste assez de temps avant la réunion.",feedback:"Couper les notifications peut faciliter sa pause, mais la tâche est déjà claire. Exiger un nouvel intervalle sans interruption risque de lui faire perdre l’occasion utile qui se présente."},{key:"b",text:"Reporter l’exercice et l’envoi à une séance plus longue, sans interruptions, demain.",feedback:"Une séance ultérieure peut convenir à une tâche plus longue. Ici, l’exemple est prêt et cinq minutes sont disponibles. L’interruption du rituel n’oblige pas à reporter son envoi."},{key:"c",text:"Envoyer l’exemple prêt maintenant et noter cet envoi séparément de la pause interrompue.",feedback:"Elle saisit l’occasion et garde des notes fidèles aux faits. L’exemple a été envoyé ; la pause a été interrompue. Aucun de ces faits ne prédit la décision du client."}],best:"c",takeaway:"Fais du minuteur un départ pour agir, sans en faire une condition.",review:"Quelle action utile as-tu tentée ? Le minuteur t’a-t-il aidé à commencer ou retardé ?",deeper:[{heading:"Ce que demande la recette des dix-sept secondes",paragraphs:["1. Choisis une expérience souhaitée ou une pensée positive. L’enseignement attribué à Abraham, transmis par Esther et Jerry Hicks, demande de fixer son attention dessus sans pensée contraire. Cela décrit le rituel, pas une procédure testée par la recherche. [manifest-P13]","2. Garde cette pensée dix-sept secondes. Certaines versions enchaînent quatre intervalles, soit soixante-huit secondes. Un minuteur peut préserver ce format reconnaissable si tu le souhaites. Mais les données examinées n’établissent aucun seuil d’attraction particulier pour l’une ou l’autre de ces durées. [manifest-P13, manifest-T16]","3. Remarque si ton attention a dérivé, sans en tirer un verdict sur ton avenir. ODA n’exige pas de recommencer avant d’agir. Les affirmations de l’enseignant selon lesquelles les pensées changeraient la réalité ou vaudraient de nombreuses heures de travail ne découlent pas des recherches examinées. [manifest-P13]","4. Termine la pause et choisis ton prochain geste. L’amorçage expérimental concerne des signaux étudiés dans certaines conditions ; il diffère de ce souhait volontaire chronométré. Tu peux garder une durée choisie dans ton rituel sans lui donner une autorité scientifique. [manifest-T16, manifest-P13]"]},{heading:"La fin du minuteur marque le début",paragraphs:["Choisis une action avant de lancer le minuteur. Pour ton portfolio, par exemple : envoyer un exemple adapté aujourd’hui. Nomme l’obstacle : recommencer jusqu’à une concentration parfaite. Puis écris : « Si le minuteur sonne, j’enverrai l’exemple prêt, même si mon attention a dérivé. » Si le minuteur ajoute de la pression, choisis un autre repère visible. [manifest-T02]","La méta-analyse de Gollwitzer et Sheeran soutient les plans « si…, alors… » précis, en moyenne, dans des tâches variées. La revue de Dai et ses collègues a trouvé un effet moyen global de l’amorçage ; dans le sous-ensemble préenregistré limité, les effets étaient plus faibles et statistiquement non concluants. Cette incertitude ne réfute pas tout amorçage. Aucune revue ne valide dix-sept ou soixante-huit secondes, ni l’idée que des pensées indésirables bloquent les résultats. [manifest-T02, manifest-T16]","La séquence ODA pause puis action est une adaptation, pas un protocole de ces recherches. Demain, note séparément l’action tentée, les retours extérieurs éventuels et la qualité de ta concentration. La pause a-t-elle fourni un repère utilisable ? Ou les répétitions ont-elles consommé l’occasion ? Garde, raccourcis ou abandonne le minuteur selon ces faits pratiques. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Boîte à souhaits",title:"Boîte à souhaits : une carte, une action datée",goal:"Garde la boîte et fais un geste réalisable vers un objectif précis.",hook:"Tes souhaits s’accumulent dans la boîte ? Choisis une carte pour agir aujourd’hui.",reason:"Quel souhait correspond à mes moyens aujourd’hui ?",paragraphs:["La boîte à souhaits contient des vœux écrits, des images ou des objets symboliques. Version courante : choisir une boîte, y mettre des intentions et les sentiments souhaités, puis les reprendre en imaginant leur réalisation. Non étayé : l’idée que la boîte réalise ces souhaits, d’après les données examinées. Une boîte déjà chez toi suffit. [manifest-P14]","Version ODA : garde les cartes. Sur une carte, ajoute un objectif précis, un obstacle, un plan « si…, alors… » et une action aujourd’hui. Examine l’essai réel demain. La recherche soutient la confrontation d’un objectif aux obstacles, accompagnée d’un plan, ainsi que le suivi des progrès en moyenne. Cette adaptation avec boîte n’est pas un ensemble testé. [manifest-T01, manifest-T03]"],example:{title:"Une carte sort de la boîte",text:"Dans sa cuisine, Thomas glisse une carte de stage du week-end dans sa boîte à chaussures. Il note son temps limité, puis appelle pour connaître les modalités de participation. Aucune formule souple n’est proposée. Demain, il notera l’appel et choisira un autre stage, plutôt que d’ajouter des souhaits."},instructions:["Choisis un contenant disponible et une carte avec un objectif précis.","Ajoute l’obstacle et ton plan ; fais une action réalisable aujourd’hui.","Demain, reprends cette carte et note l’action que tu as tentée."],action:["Demander les modalités de participation","Demander un détail du programme"],minimum:["Envoyer une question précise","Faire une demande de renseignements utile"],cue:["Après le petit déjeuner d’aujourd’hui","À l’ouverture du standard"],place:["À la table de la cuisine","Dans mon coin de travail calme"],obstacle:"Horaires peut-être incompatibles",fallback:["Demander une autre formule de présence","Contacter une autre formation adaptée"],observation:["Question envoyée ; réponse sur les horaires notée","Autre formation contactée ; réponse inconnue"],stopRule:"Utilise ce que tu as déjà. Si une option dépasse tes moyens, change d’action ou fais une pause.",scenario:"La carte du stage de Thomas mentionne un conflit d’horaires. L’organisateur peut répondre aujourd’hui. Thomas a aussi plusieurs nouvelles images à ajouter à la boîte.",question:"Quel geste vérifie le mieux si ce stage convient ?",options:[{key:"a",text:"Demander les possibilités de présence à l’organisateur, puis écrire sa réponse sur la carte du stage.",feedback:"Il vérifie l’obstacle nommé et garde une trace réelle. La réponse peut exclure ce stage ; elle l’aide quand même à choisir une prochaine action réalisable."},{key:"b",text:"Ajouter d’abord les images pour que la boîte représente toute l’expérience qu’il souhaite vivre.",feedback:"Les images peuvent rester dans son rituel préféré. Elles ne répondent pourtant pas à la question des horaires. Aujourd’hui, il peut vérifier si le stage est réalisable."},{key:"c",text:"Choisir immédiatement un autre stage, puisque le conflit d’horaires rend celui-ci incertain.",feedback:"Un autre stage peut mieux convenir, mais l’organisateur peut lever l’incertitude maintenant. Une question précise lui fournit des informations utiles avant de décider s’il change d’objectif."}],best:"a",takeaway:"Garde la carte, ajoute une action réalisable et note ce qui s’est passé.",review:"Quelle action as-tu réellement tentée pour cette carte ? Qu’as-tu appris sur l’obstacle qui se présentait ?",deeper:[{heading:"Préparer la boîte à souhaits habituelle",paragraphs:["1. Choisis une boîte ou un contenant. Le guide de la praticienne en fait un lieu pour ses intentions. ODA te propose ce qui est déjà disponible, comme une vieille boîte à chaussures ou une enveloppe. L’exercice ne demande pas d’acheter un objet particulier. [manifest-P14]","2. Écris des souhaits sur des cartes ou choisis des images pour les représenter. Le guide propose aussi de préciser pourquoi tu souhaites chaque résultat et ce que tu ressentirais. Garde ces détails pour toi si tu préfères ; une simple étiquette peut préserver le format. [manifest-P14]","3. Place les cartes ou les images dedans. Reprends-les et imagine les souhaits réalisés si ce rituel te plaît. Ces étapes décrivent la méthode vécue par une praticienne ; elles ne prouvent pas que le contenant provoque un événement extérieur. [manifest-P14]","4. Choisis une carte à relier à une occasion réelle. L’explication du guide par un champ énergétique est une croyance, pas un résultat scientifique établi. Tu peux garder le contenant symbolique tout en changeant ce que tu fais avec une carte aujourd’hui. [manifest-P14]"]},{heading:"Écrire l’obstacle au dos",paragraphs:["Garde le souhait ou l’image au recto. Au verso, écris l’objectif précis, un obstacle probable et un plan « si…, alors… ». Pour un stage : « Si le standard ouvre, je demanderai les possibilités de présence. Si les horaires ne conviennent pas, je me renseignerai sur une autre formation adaptée. » Choisis une action réalisable aujourd’hui ; préparer une carte ne compte pas comme une demande de renseignements. [manifest-T01]","Le contraste mental associé aux intentions d’implémentation relie résultat souhaité, obstacle réel et réponse prévue. Sa méta-analyse a trouvé un soutien moyen modeste à l’atteinte des objectifs, avec des résultats variables et un biais de publication possible. Harkin et ses collègues ont trouvé des bénéfices moyens en encourageant le suivi des progrès. Aucune revue n’a testé une boîte de manifestation ni prouvé que le lendemain soit le meilleur moment pour faire le bilan. [manifest-T01, manifest-T03]","Le retour du lendemain proposé par ODA permet un bilan pratique de cette carte. Note ce que tu as demandé et appris ; distingue une question envoyée d’une réponse utile ou d’une inscription. Change d’objectif si l’argent, l’accès ou le temps le rendent irréalisable. La boîte peut contenir une carte révisée, un objectif en pause ou un essai infructueux noté honnêtement. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS : état proche du sommeil",title:"SATS : laisse la scène finir, puis dors",goal:"Garde une scène douce ; prépare un geste sans retarder le sommeil.",hook:"Tu rejoues la scène parfaite au lieu de dormir ? Tu peux arrêter et agir demain.",reason:"Cette scène me laisse-t-elle dormir ?",paragraphs:["SATS, un état proche du sommeil, consiste à imaginer une courte scène de réussite, détendu et somnolent. Les pratiquants s’y imaginent et la répètent comme réelle. Certains s’endorment ainsi. Résultats mitigés pour les exercices d’imagerie apparentés. Non étayé : réaliser des souhaits par la somnolence. La simulation mentale aide en moyenne à agir, sans avantage établi au coucher. [manifest-P15, manifest-T04, manifest-T19]","Version ODA : garde une scène douce. Nomme l’objectif précis et l’obstacle, écris un plan « si…, alors… », puis répète mentalement le premier geste. Fais une action aujourd’hui, examine-la demain. La scène peut rester imparfaite. Arrête si la répétition te tient éveillé ; dormir n’est pas un test de croyance. [manifest-P15, manifest-T19]"],example:{title:"Savoir arrêter la scène",text:"Léa envoie une question sur une formation. Au coucher, elle s’imagine brièvement y participer, puis répète mentalement sa question sur le tarif pour la pause déjeuner de demain. La répétition la réveille ; elle arrête. Le lendemain, elle demande : la formation est trop chère. Elle note cette réponse et cherche une option gratuite."},instructions:["Avant de te coucher, note ton objectif, l’obstacle et ton plan.","Répète brièvement le premier geste ; fais une action utile aujourd’hui.","Donne priorité au sommeil ; examine demain l’action réellement tentée."],action:["Demander le tarif d’une formation","Demander un détail utile sur l’accès"],minimum:["Envoyer une question précise sur le tarif","Poser une question sur l’accès"],cue:["Après ma pause déjeuner d’aujourd’hui","À l’ouverture du secrétariat de la formation"],place:["À mon poste habituel","À la table de la cuisine"],obstacle:"Les images me tiennent éveillé",fallback:["Répéter en mots dans la journée","Demander directement, sans imaginer"],observation:["Question posée ; réponse notée séparément","Sommeil gêné ; scène arrêtée"],stopRule:"Arrête si les images augmentent l’éveil ou la détresse. Répète en journée ou passe cette étape ; protège ton sommeil.",scenario:"Léa sait précisément quand demander le tarif en journée. Sa scène SATS répétée la tient éveillée et ne lui semble toujours pas tout à fait réelle.",question:"Que devrait-elle choisir maintenant ?",options:[{key:"a",text:"Simplifier la scène et la répéter jusqu’à ce qu’elle paraisse assez convaincante pour arrêter.",feedback:"Simplifier peut convenir à une répétition en journée, mais la conviction n’est pas nécessaire pour arrêter. La répétition la tient éveillée ; continuer ferait passer le rituel avant le sommeil."},{key:"b",text:"Arrêter la scène, dormir et demander le tarif au moment prévu en journée.",feedback:"Elle sait déjà quand agir. Arrêter protège son sommeil sans abandonner l’objectif. Demain, elle pourra noter sa question et les informations sur le tarif qu’elle aura reçues."},{key:"c",text:"Remplacer la question sur le tarif par une séance SATS plus longue, en journée, plus facile à maîtriser.",feedback:"La journée peut mieux convenir à cet exercice facultatif, mais prolonger la scène ne donne pas le tarif. Qu’elle garde sa vraie question et considère la répétition comme une préparation."}],best:"b",takeaway:"Une courte scène peut s’arrêter avant d’être parfaite ; ton essai réel se note à part.",review:"Quelle action as-tu réellement tentée ? Les images ont-elles laissé place au sommeil ?",deeper:[{heading:"La scène dans l’enseignement SATS",paragraphs:["1. Choisis un résultat et une courte scène qui laisse entendre qu’il est arrivé. Les conférences de Neville Goddard décrivent une participation à la scène de réalisation, plutôt qu’un regard extérieur sur soi. C’est sa méthode, pas un moyen démontré de changer les événements extérieurs. [manifest-P15]","2. Assieds-toi ou allonge-toi confortablement, ferme les yeux si tu veux et détends-toi vers la somnolence. La source intègre cet état à la pratique. ODA permet une adaptation les yeux ouverts ou en mots, sans te demander de forcer la somnolence. [manifest-P15]","3. Répète la courte scène en l’imaginant réelle. Certaines versions laissent venir le sommeil dans cette sensation ; d’autres gardent une attention légère. Tu peux arrêter avant qu’elle soit convaincante. Ne reste pas éveillé pour atteindre un critère imaginaire. [manifest-P15]","4. Sépare les affirmations métaphysiques de la recette. Une revue sur l’éveil décrit les circuits interactifs du sommeil et de l’éveil ; elle ne prouve pas que la somnolence réalise les souhaits. L’enseignement de Goddard selon lequel aucune action n’est nécessaire ne découle pas de la recherche sur la simulation mentale. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Préparer un geste, préserver le sommeil",paragraphs:["Choisis un objectif précis et nomme l’obstacle avant de te coucher. Pour une formation, l’objectif peut être de vérifier si le tarif correspond à tes moyens. Répète brièvement la vraie question, avec ce que tu feras si la réponse exclut cette formation. C’est l’adaptation pratique d’ODA ; elle n’exige pas de reproduire la sensation ou la scène prescrite par Goddard. [manifest-P15, manifest-T04]","La synthèse de Cole et ses collègues a trouvé un bénéfice comportemental moyen de la simulation mentale dans des études variées, surtout avec des étudiants. Elle n’a établi ni classement fiable des sous-types ni avantage particulier au coucher. La revue sur l’éveil ne montre pas davantage que la somnolence contourne la pensée ou produit des résultats extérieurs. Les données générales sur l’imagerie ne valident pas toutes les affirmations SATS. [manifest-T04, manifest-T19]","Prévois quand poser la vraie question en journée et fais une demande utile aujourd’hui si cela convient. Demain, note question et réponse séparément des images. Si la scène te tient plus éveillé, arrête ; choisis la journée ou renonce aux images. L’action prévue peut rester en place même si la scène est inachevée. Cette séquence complète n’a pas été testée comme intervention SATS. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],a=[...o,...l,...c].sort((e,t)=>e.number-t.number).map(u),p=[...s,{id:"M01",title:"Wang, Wang et Gai · 2021 · Contraste mental et plans « si… alors… »",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 effets indépendants issus de 21 articles, 15 907 participants : bénéfice moyen modeste pour atteindre un objectif, g = 0,336 [0,229 ; 0,443]. Après correction du biais, estimation de 0,242 [0,143 ; 0,342].",limitation:"Forte variation des résultats et indices de biais de publication. Ce cours et ses exercices courts n’ont pas été testés ; aucun résultat n’est garanti."},{id:"M02",title:"Gollwitzer et Sheeran · 2006 · Plans « si… alors… » et atteinte des objectifs",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 tests indépendants, 8 461 participants : les plans précis « si… alors… » ont favorisé en moyenne l’atteinte des objectifs, d = 0,65 [0,60 ; 0,70].",limitation:"Travaux anciens et hétérogènes, sans préenregistrement systématique. Un plan ne supprime ni l’effort, ni le besoin de se souvenir, ni les contraintes pratiques, ni l’incertitude."},{id:"M03",title:"Harkin et coll. · 2016 · Suivi des progrès vers un objectif",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 expériences, 19 951 participants au total. L’analyse de l’atteinte des objectifs portait sur 18 398 participants : d = 0,40 [0,32 ; 0,48]. Une analyse de sensibilité aux petites études estimait 0,19 [0,10 ; 0,28].",limitation:"Objectifs et interventions variés. Les liens observés entre caractéristiques des études et effets n’imposent pas de rendre ses progrès publics. Ni ce carnet précis, ni ce rythme de bilan, ni le cours ODA n’ont été validés."},{id:"M04",title:"Cole et coll. · 2021 · Simulation mentale et changement de comportement",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 études, 123 effets, 5 685 participants : effet global de la simulation mentale, g = 0,49 [0,37 ; 0,62]. La comparaison globale entre types de simulation n’était pas statistiquement significative.",limitation:"Échantillons surtout étudiants, simulations variées. Imaginer uniquement les étapes reposait sur cinq effets, avec une estimation non concluante. Aucun classement fiable des types de simulation, ni validation de cet exercice court."},{id:"M07",title:"Dixon, Hornsey et Hartley · 2025, en ligne en 2023 · Croyance en la manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Trois enquêtes en ligne aux États-Unis, 1 023 participants : la croyance en la manifestation était corrélée à certaines prises de risque financières déclarées et aux faillites déclarées, mais pas au revenu ni au niveau d’études déclarés.",limitation:"Ces associations n’établissent pas de cause et ne testent pas objectivement chaque technique de manifestation. Des résultats financiers autodéclarés ne permettent pas de prédire le parcours d’une personne."},{id:"M10",title:"Gollwitzer et Brandstätter · 1997 · Prévoir une occasion précise pour commencer",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"Dans l’étude 2, 86 étudiants devaient rédiger un compte rendu. Parmi les 36 ayant rendu un texte identifiable, 12/17 avec un plan contre 6/19 témoins l’ont écrit sous deux jours.",limitation:"Les 71 % contre 32 % concernent ceux qui ont rendu leur texte, pas toutes les personnes recrutées. Le plan n’a pas augmenté la participation globale. Tâche étudiante très précise ; le cours ODA n’a pas été validé."},{id:"M11",title:"Oettingen et coll. · 2015 · Plans et organisation du calendrier",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"L’étude 1 analysait 84 étudiants. La comparaison prévue favorisait le contraste mental avec plans « si… alors… » pour les heures planifiées, p = 0,03 ; test global, p = 0,057.",limitation:"On mesurait les heures planifiées, pas le travail réalisé ni la productivité. Les réponses incomplètes étaient exclues. Ni l’adaptation courte du cours, ni sa distinction des contraintes extérieures n’ont été testées."},{id:"M14",title:"NIMH · Trouver de l’aide en santé mentale",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Ces recommandations officielles indiquent comment obtenir des soins qualifiés ou une aide de crise face à la détresse, à des difficultés de fonctionnement ou à un danger immédiat.",limitation:"Recommandations, pas étude d’efficacité. ODA ne diagnostique ni ne traite les troubles mentaux ; hors des États-Unis, utilise les services de soins et d’urgence locaux."},{id:"manifest-positive-fantasies",title:"Kappes et Oettingen · 2011 · Rêveries positives idéalisées",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Quatre expériences surtout étudiantes ont observé une baisse d’énergie immédiate après certaines rêveries positives idéalisées. L’étude 3 comparait ces rêveries à des rêveries neutres ou libres, pas à des rêveries critiques.",limitation:"Petites expériences courtes. L’optimisme et l’imagination ne sont pas tous nocifs. Ni une boucle récurrente de rêveries, ni un signal cérébral d’objectifs accomplis n’ont été mesurés."},{id:"manifest-belief-study",title:"Dixon, Hornsey et Hartley · 2025, en ligne en 2023 · Croyance en la manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Trois enquêtes en ligne aux États-Unis, 1 023 participants au total : la croyance en la manifestation était liée à la confiance et à certaines prises de risque financières déclarées, dont des faillites. Aucun lien avec le revenu ni le niveau d’études déclarés.",limitation:"Ces associations n’établissent pas de cause et ne testent pas objectivement chaque technique. Des résultats autodéclarés ne prédisent pas le parcours d’une personne."},{id:"manifest-murphy",title:"Joseph Murphy · The Power of Your Subconscious Mind · Présentation de l’éditeur",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"L’éditeur présente le livre grand public de Murphy et ses enseignements sur l’imagination et la croyance.",limitation:"Présentation éditoriale, pas étude contrôlée. Les passages précis sur le rituel du coucher n’ont pas été vérifiés. Rien ici ne démontre une attraction de richesse, une guérison ou un apprentissage particulièrement efficace au coucher."}],i=[{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"fr",title:"Ton rêve attend encore ? Fais quelque chose d’utile",goal:"Produis un travail utilisable pour l’objectif que tu choisis.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Encore une semaine à vouloir une autre vie ? Fais avancer un souhait concrètement.",reason:{id:"manifest-1-reason",label:"Cet objectif est-il le tien ? Mérite-t-il ton temps ?",kind:"text",maxLength:160,optional:!0,suggestions:["Mon objectif ; le téléphone attendra ce soir","Priorité familiale ; les finitions attendront","Objectif d’un autre ; revoir le temps accordé","Je ne sais pas si c’est mon objectif"]},why:{id:"manifest-1-purpose",label:"Qu’est-ce que ce geste permettrait dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Trouver un meilleur emploi, c’est un résultat. Améliorer une ligne de ton CV, c’est une action. D’autres décident de te rappeler ou non. Choisis un travail utile sans mesurer ton effort à leur réponse.","Dans une étude auprès d’étudiants, choisir où et quand commencer a favorisé le respect du délai parmi ceux qui ont rendu leur compte rendu. Cela n’a pas augmenté la participation globale. Un plan peut aider à démarrer ; il ne garantit pas le résultat. Aujourd’hui, écris une ligne, une réponse ou une demande utile. Garde cet objectif dans le cours ; rapporte les faits."],example:{title:"Julien se lance",text:"Après dîner, à la table de la cuisine, Julien consacre dix minutes à sa recherche d’emploi en logistique. Il réécrit une ligne sur huit créneaux planifiés à l’entrepôt. La formulation reste maladroite. Il l’enregistre et note la modification. Aucun employeur ne l’a vue. Demain, il pourra améliorer ce premier jet."}},move:{invitation:"Choisis ton geste utile ; les suggestions reprennent le CV de Julien.",instructions:["Précise le document, la question ou l’objet à modifier.","Fais ton minimum ; note-le séparément de toute réponse extérieure."],prompts:[],suggestions:{action:["Réécrire une ligne du CV sur les plannings","Demander quel détail manque au CV","Créer un planning d’équipes fictif sans créneau vacant"],minimum:["Enregistrer une phrase du CV sur les plannings","Envoyer la question sur le détail du CV","Enregistrer un planning d’équipes fictif sans créneau vacant"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1},{label:"Dans deux jours",daysFromToday:2}],cue:["Après avoir débarrassé la table du dîner","À la fin du déjeuner","Après ma boisson du matin"],place:["À ma table de cuisine","À un poste de la médiathèque","Dans mon CV"],minutes:[10,2,5],fallback:["Décrire simplement un changement de planning","Choisir et préciser un autre créneau disponible","Demander un accès informatique à la médiathèque"],observation:["La phrase du CV que j’ai enregistrée","Ai-je envoyé la question sur le CV ?","Ce qui a empêché mon minimum"]},suggested:{action:"Réécrire une ligne du CV sur les plannings",minimum:"Enregistrer une phrase du CV sur les plannings",minutes:10,cueHint:"Après avoir débarrassé la table du dîner",placeHint:"À ma table de cuisine",obstacleHint:"J’ai moins de temps que prévu",fallbackHint:"Décrire simplement un changement de planning",observationHint:"La phrase du CV que j’ai enregistrée"},accessibleAlternative:"Écris, dicte ou utilise tes outils habituels ; demande une aide pratique si nécessaire.",stopRule:"Suspends les gestes dangereux ou trop coûteux ; choisis plutôt une aide pratique."},result:{question:"As-tu fait le minimum choisi ?",observationPrompt:"Qu’as-tu fait ou produit pendant cet essai ?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Julien a trouvé une offre adaptée et dispose de dix minutes avant le dîner. Son CV ne décrit pas le travail de planning demandé.",question:"Quel premier essai serait le plus utile ?",options:[{id:"manifest-1-research-more",text:"Comparer d’autres offres pour vérifier que ce poste correspond bien à la vie qu’il souhaite.",feedback:"Comparer les postes peut préciser un objectif. Cette offre convient déjà. Il manque une description utilisable de l’expérience de Julien. Améliorer cette ligne occupe utilement le temps disponible."},{id:"manifest-1-improve-line",text:"Réécrire une ligne du CV pour cette offre, enregistrer ce premier jet et noter les points à améliorer.",feedback:"Julien obtient quelque chose d’utilisable en restant dans les dix minutes. Le texte pourra nécessiter un avis et l’employeur pourra ne pas répondre. Le travail réalisé reste bien réel."},{id:"manifest-1-clarify-future",text:"Décrire en détail sa journée de travail idéale avant de décider quoi écrire sur le CV.",feedback:"Une journée idéale peut guider des choix futurs. Julien a déjà retenu un poste adapté. Ajouter une description repousse ce manque concret. Écrire la ligne du CV permettra ensuite de voir quoi améliorer."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"Fais avancer ton souhait par un geste utile. Note ce geste séparément de la réponse espérée.",followUp:{questionId:"manifest-1-return",question:"Quel travail utilisable reste de ton essai enregistré ?",observationPrompt:"Que s’est-il passé au moment prévu ?",adjustmentPrompt:"Quel changement conviendrait à ta prochaine occasion ?"}},goDeeper:{sections:[{heading:"Ce qu’un plan pour commencer peut aider à faire",paragraphs:["En 1997, Gollwitzer et Brandstätter ont confié un compte rendu sur Noël à 86 étudiants munichois. Ceux qui planifiaient choisissaient où et quand commencer, imaginaient cette occasion, s’engageaient à démarrer et notaient leurs choix. Parmi les 36 auteurs de textes identifiables, 12/17 avec un plan et 6/19 témoins ont écrit sous les deux jours demandés. Ces proportions concernent les étudiants ayant rendu un texte identifiable, pas toutes les personnes recrutées. Le plan n’a pas augmenté la participation globale. [M10]","Choisis une occasion précise pour réaliser un travail utile. Cette adaptation n’a pas été testée dans l’étude du compte rendu de Noël. Une date ne dit pas d’où viendra le temps disponible. Choisis un événement reconnaissable et un lieu accessible. Si les moyens manquent, les demander peut être ton geste concret. Note alors une demande, même si l’aide n’est pas encore arrivée."]},{heading:"Un souhait ne décide pas pour les autres",paragraphs:["La synthèse de Wang (2021) réunissait 24 effets indépendants issus de 21 articles, avec 15 907 participants. Associer résultat souhaité, obstacle et réponse « si… alors… » montrait un bénéfice moyen modeste pour atteindre les objectifs : g = 0,336, intervalle de confiance à 95 % de 0,229 à 0,443. Les résultats variaient beaucoup et une correction du biais de publication réduisait l’estimation. Cela soutient une planification réaliste, sans promesse pour ce cours. [M01]","Dixon et ses collègues ont étudié la croyance en la manifestation dans trois enquêtes américaines en ligne totalisant 1 023 participants. Cette croyance était corrélée à certains risques financiers déclarés et aux faillites déclarées, mais pas au revenu ni au niveau d’études déclarés. Ces liens ne montrent pas que la croyance cause la faillite et ne testent pas objectivement chaque exercice de manifestation. [M07] Utilise ton souhait pour choisir un travail et évaluer les contraintes. N’en conclus pas que tes pensées ont attiré une occasion, causé tes difficultés ou rendu un résultat mérité. L’argent, les soins à recevoir ou à apporter, l’accès aux ressources et les décisions d’autrui comptent toujours."]}],sourceIds:["M10","M01","M07"]}},{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"fr",title:"Encore en train de répéter ? Termine par un geste",goal:"Répète mentalement un point difficile, puis fais la prochaine partie utile de ta tâche.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"Ta vie rêvée est facile à imaginer. Mais que fais-tu devant la page blanche ?",reason:{id:"manifest-2-reason",label:"Une répétition mentale aidera-t-elle ou remplacera-t-elle l’essai ?",kind:"text",maxLength:160,optional:!0,suggestions:["Elle révèle une consigne manquante","Elle retarde une phrase déjà prête","Je n’ai aucune note de répétition mentale"]},why:{id:"manifest-2-purpose",label:"Qu’est-ce que ce geste permettrait dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Reprends ta tâche et tes notes. Répéter mentalement, c’est imaginer un geste précis, comme prononcer la première phrase. Lister les étapes est une autre préparation. Aucune des deux ne constitue l’essai réel.","Une synthèse a trouvé des bénéfices moyens de la simulation mentale sur le comportement, sans établir quel type serait le meilleur. Elle ne valide pas cette courte répétition. Utilise-la pour repérer un blocage et une réponse possible. Si les images ne viennent pas, décris le geste avec des mots. Puis écris la prochaine ligne utile de la même tâche."],example:{title:"Julien devant la ligne vide",text:"Julien reprend son CV après le dîner. Pendant trente secondes, il s’imagine décrire un changement de planning difficile. Il s’attend à bloquer et répète ce début : « Réorganisé huit créneaux quand… » Puis il écrit une phrase utilisable. Il enlève deux mots et note une question de relecture. La répétition n’avait pas prévu les détails nécessaires."},rehearsal:{label:"Préparation facultative",steps:["Décris le prochain geste et un point où tu risques de bloquer.","Répète mentalement ta première réponse une fois. C’est de la préparation."]}},move:{invitation:"Garde ta tâche ; adapte ces exemples.",instructions:["Garde ton geste, ton minimum, le signal et le lieu ; cible le blocage.","Sans plan, précise ton geste et un créneau disponible avant d’enregistrer.","Répète mentalement une fois, puis agis. Répéter prépare seulement."],prompts:[],suggestions:{action:["Répéter mentalement, puis écrire ma phrase de CV","Répéter mentalement, puis demander quel détail manque","Suivre des étapes écrites ; corriger une date"],minimum:["Enregistrer la phrase après la répétition mentale","Envoyer la question sur le détail du CV","Enregistrer une date corrigée du CV"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1},{label:"Dans deux jours",daysFromToday:2}],cue:["Après avoir débarrassé la table du dîner","À la fin du déjeuner","À l’ouverture du document du CV"],place:["À ma table de cuisine","À un poste de la médiathèque","Dans mon CV"],minutes:[5,2,10],fallback:["Cesser la répétition mentale ; décrire un changement d’horaires","Sans images, suivre la première étape écrite","Demander à mon relecteur quel détail manque"],observation:["Ce que la répétition mentale n’avait pas prévu","La phrase du CV que j’ai produite","Ai-je seulement répété mentalement ?"]},suggested:{action:"Répéter mentalement, puis écrire ma phrase de CV",minimum:"Enregistrer la phrase après la répétition mentale",minutes:5,cueHint:"Après avoir débarrassé la table du dîner",placeHint:"À ma table de cuisine",obstacleHint:"Je peaufine la répétition mentale au lieu de commencer",fallbackHint:"Cesser la répétition mentale ; décrire un changement d’horaires",observationHint:"Ce que la répétition mentale n’avait pas prévu"},accessibleAlternative:"Écris, dicte ou utilise tes outils habituels ; demande une aide pratique si nécessaire.",stopRule:"Si planifier au lit te tient éveillé, arrête et choisis un moment en journée."},result:{question:"As-tu fait le minimum choisi ?",observationPrompt:"Qu’as-tu fait ou produit pendant cet essai ?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Julien sait comment commencer sa phrase de CV et le document est prêt. Il est tenté de répéter mentalement toute la candidature.",question:"Quel geste aiderait cet essai ?",options:[{id:"manifest-2-full-rehearsal",text:"Répéter mentalement toute la candidature pour choisir le meilleur début avant d’écrire quoi que ce soit.",feedback:"Une répétition complète peut préparer la suite. Julien a déjà un début utilisable et son document est prêt. Refaire l’ensemble retarde l’essai possible maintenant. Il peut écrire sa phrase puis l’examiner."},{id:"manifest-2-new-goal-scene",text:"Imaginer sa première journée dans ce poste pour se remotiver, puis reprendre sa candidature plus tard.",feedback:"Imaginer le poste peut rappeler pourquoi il compte. Cela ne teste pas le début préparé par Julien. Il peut l’écrire maintenant dans le document, puis voir ce qui était plus difficile que prévu."},{id:"manifest-2-perform-opening",text:"Répéter mentalement la première phrase une fois, l’écrire dans le document et comparer la difficulté réelle à celle prévue.",feedback:"La préparation débouche ici sur un geste réel. La phrase écrite donne à Julien quelque chose à examiner. Sa qualité et son inconfort restent à évaluer ; ce ne sont pas des conditions pour reconnaître l’essai."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"Termine la préparation utile par un vrai geste. Note les deux séparément.",followUp:{questionId:"manifest-2-return",question:"Qu’est-ce qui différait entre répéter mentalement ton geste et le faire ?",observationPrompt:"Que s’est-il passé au moment prévu ?",adjustmentPrompt:"Quel changement conviendrait à ta prochaine occasion ?"}},goDeeper:{sections:[{heading:"Ce que les recherches sur la simulation permettent de comparer",paragraphs:["La synthèse de Cole et ses collègues, publiée en 2021, réunissait 94 études, 123 effets et 5 685 participants. L’effet global de la simulation mentale sur le comportement était g = 0,49, intervalle de confiance à 95 % de 0,37 à 0,62. Les échantillons étaient surtout étudiants. Contenu, durée et résultats mesurés variaient : cette moyenne ne prédit pas l’effet de ton exercice court. [M04]","La synthèse distinguait réfléchir aux étapes et imaginer l’exécution d’une tâche. L’estimation pour les seules étapes reposait sur cinq effets, avec un intervalle de confiance incluant l’absence d’effet. La comparaison globale des types n’était pas statistiquement significative. Des moyennes plus élevées dans certains sous-groupes n’établissent donc aucun gagnant fiable. Un graphique ne t’invite pas à visualiser plus fort. Cette leçon utilise une répétition pour repérer un détail pratique, puis te propose d’essayer la tâche. La description écrite est une option d’accessibilité, sans équivalence démontrée avec les images."]},{heading:"Prépare-toi pour une occasion, puis saisis-la",paragraphs:["Dans l’expérience sur le compte rendu, les participants imaginaient un lieu et un moment précis pour commencer. La comparaison des délais concernait les auteurs identifiables de textes rendus et une tâche étudiante très précise. Elle n’établit ni un scénario mental universel, ni un avantage à répéter au lit. [M10] Ici, la préparation est utile quand elle t’aide à faire la prochaine partie de la tâche déjà liée à ton objectif.","Tu peux découvrir un mot de passe manquant, une consigne floue ou une phrase que tu ne sais pas encore expliquer. Réinitialiser un mot de passe prépare la tâche ; envoyer les informations demandées la fait avancer. Distingue les deux dans tes notes. Si planifier au coucher te tient éveillé, arrête et choisis un moment en journée. C’est une adaptation pratique du cours. La répétition courte est facultative : ni rituel validé, ni préalable obligatoire. Aucune image nette ni émotion particulière n’est requise."]}],sourceIds:["M04","M10"]}},{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"fr",title:"L’obstacle est réel. Change les conditions",goal:"Pars du dernier essai pour tester une réponse réalisable à l’obstacle.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Garde d’enfants, accès manquant ou épuisement ? Y croire plus fort ne réorganise pas ta journée.",reason:{id:"manifest-3-reason",label:"Que peux-tu changer maintenant ? Où as-tu besoin d’aide ?",kind:"text",maxLength:160,optional:!0,suggestions:["Ordinateur partagé ; convenir d’un créneau","Je peux réduire la modification du CV","Aider un proche ; aucun créneau aujourd’hui","Je n’ai pas encore rencontré d’obstacle"]},why:{id:"manifest-3-purpose",label:"Qu’est-ce que ce geste permettrait dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Reprends l’objectif et tes notes. Pas encore essayé ? Précise un obstacle probable. « L’ordinateur partagé est pris après le dîner » permet de chercher une réponse. « Je manque de discipline » ne précise pas ce qui bloque.","Des études associant résultat souhaité, obstacle réel et réponse « si… alors… » ont trouvé des bénéfices moyens modestes. L’inconfort n’est pas un mécanisme établi. L’argent, les soins à recevoir ou l’aide à apporter, le temps et l’accès sont des contraintes, pas un défaut de croyance. Teste un changement : tâche réduite, créneau disponible ou demande d’aide précise. Une demande signifie avoir demandé, pas avoir reçu l’aide."],example:{title:"Julien change de créneau",text:"Julien voulait retravailler son CV après dîner, mais sa fille utilisait l’ordinateur partagé pour ses devoirs. Il note ce conflit. Il demande dix minutes avant dîner le lendemain. Ils se mettent d’accord. Il améliore alors une ligne puis s’arrête. La candidature nécessite encore du travail."}},move:{invitation:"Besoin d’accès ? Choisis « Adapter ce geste », puis « Soutien ». Nomme ton contact. Exemple : demande d’ordinateur.",instructions:["Si l’accès est convenu, garde ton geste, ton minimum, le signal et le lieu.","Sans accès, précise la personne, la ressource et le créneau dans ta demande d’aide.","Note séparément la demande, l’aide reçue et le travail réalisé."],prompts:[],suggestions:{action:["Demander l’ordinateur à ma fille avant le dîner","Demander les créneaux informatiques à la médiathèque"],minimum:["Demander dix minutes d’ordinateur à ma fille","Envoyer la question sur l’accès informatique"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1},{label:"Dans deux jours",daysFromToday:2}],cue:["Quand on organise les devoirs à la maison","Après le déjeuner d’aujourd’hui","Après avoir débarrassé la table du dîner"],place:["À ma table de cuisine","Dans le formulaire de la médiathèque","À un poste de la médiathèque"],minutes:[5,2,10],fallback:["Demander un accès informatique à la médiathèque","Demander un créneau d’ordinateur à un proche","Faire une pause jusqu’à un créneau convenu"],observation:["La demande d’accès et la réponse éventuelle","Un créneau d’ordinateur a-t-il été convenu ?","Ai-je fait la modification de CV choisie ?"]},suggested:{action:"Demander l’ordinateur à ma fille avant le dîner",minimum:"Demander dix minutes d’ordinateur à ma fille",minutes:5,cueHint:"Quand on organise les devoirs à la maison",placeHint:"À ma table de cuisine",obstacleHint:"Ma fille ne peut pas me laisser l’ordinateur",fallbackHint:"Demander un accès informatique à la médiathèque",observationHint:"La demande d’accès et la réponse éventuelle",kind:"support"},accessibleAlternative:"Écris, parle ou fais-toi aider. Choisis « Adapter ce geste » pour travailler une fois l’accès convenu.",stopRule:"Si l’exercice te submerge ou que la situation est dangereuse, fais une pause et cherche un soutien adapté."},result:{question:"As-tu fait le minimum choisi ?",observationPrompt:"Qu’as-tu fait ou produit pendant cet essai ?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Le CV de Julien et les devoirs nécessitent le même ordinateur le soir. Dix minutes avant le dîner sont possibles s’ils se mettent d’accord.",question:"Quelle réponse convient à cet obstacle ?",options:[{id:"manifest-3-arrange-opening",text:"Convenir des dix minutes disponibles et les utiliser pour améliorer une ligne du même document.",feedback:"Cela change la condition qui bloquait la tâche en gardant un minimum utile. Il faut encore un accord. Si le créneau n’est pas confirmé, noter seulement la demande préserve les faits."},{id:"manifest-3-keep-evening",text:"Garder le rendez-vous du soir et répéter mentalement plus longtemps pour être prêt quand l’ordinateur sera disponible.",feedback:"Répéter peut préparer les mots, mais ne résout pas le conflit d’accès. Julien dispose d’un autre créneau possible. Il peut convenir de ce moment avant d’ajouter une préparation supplémentaire."},{id:"manifest-3-wait-week",text:"Attendre que les devoirs se calment la semaine prochaine, puis reprendre la longue séance de CV prévue au départ.",feedback:"Attendre peut convenir quand aucun créneau n’est possible. Ici, un moment plus court pourrait être organisé maintenant. Cette option mérite un essai avant de reporter automatiquement tout le travail."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Précise ce qui bloque. Adapte la tâche ou demande l’aide dont tu as besoin.",followUp:{questionId:"manifest-3-return",question:"As-tu demandé l’accès ou fait le geste prévu ? Quel accord manque encore ?",observationPrompt:"Que s’est-il passé au moment prévu ?",adjustmentPrompt:"Quel changement conviendrait à ta prochaine occasion ?"}},goDeeper:{sections:[{heading:"Un obstacle renseigne ; l’inconfort n’est pas une recette",paragraphs:["La synthèse de 2021 sur le contraste mental avec plan a trouvé une amélioration moyenne modeste de l’atteinte des objectifs, à partir de 24 effets indépendants. La forte variation et les indices de biais de publication limitent la certitude. Elle n’a pas isolé l’inconfort comme ingrédient actif. Nommer une difficulté peut être désagréable ; l’exercice ne demande pas d’accentuer volontairement la détresse. [M01]","La procédure de 2015 d’Oettingen et ses collègues demandait aux étudiants de développer un résultat souhaité et un obstacle principal, de choisir une réponse, de former un plan reliant obstacle et action, puis d’ajouter les lieu et moment habituels. Dans l’étude 1, la comparaison prévue favorisait cette méthode pour les heures inscrites au calendrier. On mesurait la planification, pas le travail réalisé ; le test global des groupes restait non concluant. [M11] ODA ajoute une vérification pratique de faisabilité et un essai réel. Ni cette version courte, ni sa distinction entre contraintes extérieures et réponses personnelles n’ont été validées séparément."]},{heading:"Quand la bonne réponse consiste à demander de l’aide",paragraphs:["Distingue le résultat souhaité des conditions pour le poursuivre. Un outil manquant demande un accès ; une situation dangereuse, une protection ; des responsabilités envers un proche, parfois un autre créneau. C’est un choix pédagogique nourri par les recherches sur les plans, pas une classification universelle des obstacles. Une demande d’aide devient concrète quand elle précise ce dont tu as besoin et à quel moment. [M01, M11]","Sans réponse, note la demande et l’absence de retour. Ne note ni aide reçue ni tâche terminée. Tu peux choisir un autre geste possible, revoir l’objectif ou faire une pause. Face à une détresse persistante ou à des difficultés importantes au quotidien, cherche un soutien qualifié au lieu d’intensifier l’exercice. Le NIMH indique des recours aux soins et à l’aide de crise ; il ne démontre pas qu’ODA traite un trouble. [M14] Tes prochaines notes doivent décrire le geste choisi, y compris la protection ou le soutien, sans transformer l’obstacle initial en manque de croyance."]}],sourceIds:["M01","M11","M14"]}},{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"fr",title:"N’attends plus le bon état d’esprit",goal:"Choisis un signal reconnaissable et une petite réponse au blocage observé.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"« Quand je me sentirai prêt », ça recule toujours. Choisis un moment reconnaissable.",reason:{id:"manifest-4-reason",label:"La dernière fois, qu’a coûté le report du geste ?",kind:"text",maxLength:160,optional:!0,suggestions:["Comparé des exemples ; rien écrit","Attendu d’être prêt ; CV inchangé","Aider un proche ; aucun créneau sûr","Pas de signal précédent ; les mots me freinent"],help:"Pas encore essayé ? Précise une hésitation possible."},why:{id:"manifest-4-purpose",label:"Qu’est-ce que ce geste permettrait dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Le signal et la réponse à un obstacle ont des rôles différents. « Après avoir débarrassé, écrire une ligne du CV » choisit le moment. « Si je bloque, décrire un changement de planning » aide pendant ce créneau.","Des recherches sur divers objectifs ont trouvé qu’un plan précis « si… alors… » favorisait en moyenne le passage à l’action. Il ne supprime pas tout effort de mémoire, toute difficulté ni les contraintes pratiques. Garde ta tâche ; réponds à l’obstacle noté, s’il existe. Choisis un signal visible et une réponse réalisable. S’il n’arrive pas, note l’absence d’occasion et choisis un autre créneau."],example:{title:"Julien repère le signal",text:"Julien pose une note près de l’ordinateur partagé : « Après avoir débarrassé, améliorer une ligne. Si je bloque, décrire un changement de planning. » Jeudi, il débarrasse et remarque la note. Il écrit une ligne utile, mais ne termine pas la rubrique avant de reprendre ses responsabilités familiales. Il note ces faits."}},move:{invitation:"Garde ta tâche et ton créneau. Les exemples reprennent le CV de Julien.",instructions:["Garde ton geste, ton minimum, le signal et le lieu, sauf nécessité.","Précise une réponse courte à ton blocage."],prompts:[],suggestions:{action:["Après dîner, écrire une phrase sur les plannings","Après déjeuner, envoyer la question sur le CV","Après le thé, corriger une date du CV"],minimum:["Enregistrer une phrase du CV sur les plannings","Envoyer la question sur le détail du CV","Enregistrer une date corrigée du CV"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1},{label:"Dans deux jours",daysFromToday:2}],cue:["Après avoir débarrassé les assiettes","À la fin du déjeuner","Quand je repose ma tasse de thé"],place:["À ma table de cuisine","Dans mon CV","À un poste de la médiathèque"],minutes:[5,2,10],fallback:["Décrire un changement de planning en une phrase","Choisir et préciser un autre créneau disponible","Demander un accès informatique à la médiathèque"],observation:["Le signal était-il présent et repéré ?","Ai-je décrit le changement de planning ?","La modification du CV que j’ai enregistrée"]},suggested:{action:"Après dîner, écrire une phrase sur les plannings",minimum:"Enregistrer une phrase du CV sur les plannings",minutes:5,cueHint:"Après avoir débarrassé les assiettes",placeHint:"À ma table de cuisine",obstacleHint:"Le moment arrive, mais je bloque sur les mots",fallbackHint:"Décrire un changement de planning en une phrase",observationHint:"Le signal était-il présent et repéré ?"},accessibleAlternative:"Écris, dicte ou utilise tes outils habituels ; demande une aide pratique si nécessaire.",stopRule:"Respecte tes responsabilités envers les personnes dont tu t’occupes et ta sécurité ; choisis un autre créneau si celui-ci ne convient plus."},result:{question:"As-tu fait le minimum choisi ?",observationPrompt:"Qu’as-tu fait ou produit pendant cet essai ?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Julien a cinq minutes après avoir débarrassé la table du dîner. Son CV et un exemple exact de changement de planning sont prêts, mais il bloque sur les mots.",question:"Quel plan aide à commencer puis à dépasser le blocage ?",options:[{id:"manifest-4-mood-cue",text:"Quand il se sentira plus lucide après le dîner, améliorer la rubrique du CV pendant cinq minutes avec ses meilleurs exemples.",feedback:"Se sentir plus lucide serait agréable, mais ce moment reste incertain. Le dîner débarrassé fournit un repère observable. La réponse doit tenir dans les cinq minutes disponibles."},{id:"manifest-4-full-section",text:"Après avoir débarrassé, comparer trois exemples de planning avant de choisir le meilleur pour la ligne du CV.",feedback:"Comparer peut aider à choisir. Julien possède déjà un exemple exact ; en chercher d’autres consommerait ses cinq minutes. Décrire ce changement d’abord lui donnera une vraie phrase à retravailler."},{id:"manifest-4-cue-and-response",text:"Après avoir débarrassé, améliorer une ligne ; si les mots bloquent, décrire simplement un changement réel de planning.",feedback:"Le moment de départ et le blocage ont chacun leur réponse. Julien peut essayer avec son CV déjà prêt. Le plan aide à agir sans promettre une mémoire sans effort ni une rubrique terminée."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Choisis quand commencer et quoi faire si tu bloques. Vérifie ensuite ce qui s’est passé.",followUp:{questionId:"manifest-4-return",question:"As-tu repéré le signal et pu utiliser ta réponse prévue ?",observationPrompt:"Que s’est-il passé au moment prévu ?",adjustmentPrompt:"Quel changement conviendrait à ta prochaine occasion ?"}},goDeeper:{sections:[{heading:"Ce qu’un plan précis peut soutenir",paragraphs:["Le chapitre de Gollwitzer et Sheeran, publié en 2006, réunissait 94 tests indépendants avec 8 461 participants. L’effet moyen des plans « si… alors… » sur l’atteinte des objectifs était d = 0,65, intervalle de confiance à 95 % de 0,60 à 0,70. Tâches et procédures variaient ; ces recherches anciennes n’étaient pas systématiquement préenregistrées. Rien ne garantit donc l’efficacité de n’importe quelle phrase écrite par un apprenant. [M02]","L’expérience sur le compte rendu demandait aux étudiants de choisir où et quand commencer. La comparaison des délais concernait les auteurs de textes rendus identifiables, pas toutes les personnes auxquelles la tâche était confiée. [M10] La leçon pratique est plus limitée que « un plan remplace la volonté ». Choisis une réponse à l’avance, puis vérifie si la situation est arrivée, si tu l’as repérée et si la réponse convenait. Garde les rappels extérieurs utiles. Une note près d’un outil est une option ODA, pas une garantie démontrée de la remarquer."]},{heading:"Deux rôles dans un même essai qui se poursuit",paragraphs:["Le moment choisi pour commencer précise quand essayer la tâche. Ta réponse à l’obstacle précise quoi faire si la difficulté observée apparaît. La procédure de contraste mental étudiée reliait obstacle et réponse, puis ajoutait les lieu et moment habituels. Elle n’établissait pas que chacun a besoin de deux règles distinctes. [M11] Ce cours sépare leurs rôles pour mieux comprendre ce qui bloque ton essai en cours.","Si le créneau prévu ne se présente jamais, rien ne permet de dire que ta réponse à l’obstacle a échoué. S’il arrive sans que tu le remarques, change le signal ou le rappel. Si tu le remarques mais que la réponse est trop grande, réduis la prochaine partie utile de la tâche. Ce sont des choix à tester, pas des conclusions prouvées par un carnet personnel. Garde chaque ancien essai lié à son minimum initial. Un nouveau plan ne transforme pas un essai incomplet en travail terminé. Examine ton geste réel ; soutien, repos, pause ou nouvel objectif restent possibles."]}],sourceIds:["M02","M10","M11"]}},{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"fr",title:"Aucun résultat ? Regarde ce que tu as fait",goal:"Tes notes guideront une suite réalisable et le bilan de la semaine prochaine.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"CV prêt, candidature pas envoyée ? As-tu essayé ou seulement préparé ?",reason:{id:"manifest-5-reason",label:"Pourquoi continuer, modifier ou arrêter cette voie ?",kind:"text",maxLength:160,optional:!0,suggestions:["Premier jet utilisable ; l’envoyer","Conflits répétés ; changer de créneau","Avis précis ; revoir la phrase floue","Aucun essai ; en choisir un premier"]},why:{id:"manifest-5-purpose",label:"Qu’est-ce que ce geste permettrait dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Relis les notes du même objectif. Sépare tes plans, tes répétitions mentales, tes actions et ce que tu as reçu d’autrui. Un premier jet enregistré montre un travail de rédaction. Il ne prouve ni l’envoi d’une candidature ni l’intérêt d’un employeur.","Une synthèse de 138 expériences trouvait des bénéfices moyens du suivi renforcé des progrès. Elle n’a validé ni ces notes précises ni un rythme idéal de bilan. Pars des faits : répéter un geste réalisable, modifier un problème, demander un avis ou arrêter un objectif inadapté. Sans essai, reconnais ce manque et fais une première partie utile."],example:{title:"Julien choisit la suite de sa semaine",text:"Julien relit trois modifications datées et un créneau d’ordinateur manqué. Son CV est plus clair, mais il n’a envoyé aucune candidature. Il choisit une offre adaptée, vérifie les critères et envoie la version préparée vendredi. Il note l’envoi et prévoit un bilan la semaine suivante. Toujours aucune réponse."}},move:{invitation:"Garde ce qui convenait, précise la suite. L’exemple reprend une candidature prête à envoyer.",instructions:["Pour recommencer, garde le minimum et le créneau ; change seulement ce qui a bloqué.","Sans notes, précise un premier geste et son minimum avant d’enregistrer.","Demander une information signifie avoir demandé, pas avoir terminé la tâche bloquée."],prompts:[],suggestions:{action:["Envoyer la candidature préparée pour l’offre choisie","Demander au recruteur de préciser un critère","Réviser une phrase du CV selon l’avis reçu"],minimum:["Envoyer une fois la candidature préparée","Envoyer la question sur le critère demandé","Enregistrer la phrase du CV révisée"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1},{label:"Dans deux jours",daysFromToday:2}],cue:["À la fin du déjeuner","Après avoir débarrassé la table du dîner","À l’ouverture de la page de candidature"],place:["À ma table de cuisine","À un poste de la médiathèque","Dans le formulaire de candidature de l’offre"],minutes:[10,2,5],fallback:["Demander au recruteur de préciser le critère","Demander un avis sur la phrase peu claire","Faire une pause en attendant l’information nécessaire"],observation:["L’envoi et sa confirmation éventuelle","La demande d’information et la réponse attendue","Ce qui échappe encore à mon contrôle"]},suggested:{action:"Envoyer la candidature préparée pour l’offre choisie",minimum:"Envoyer une fois la candidature préparée",minutes:10,cueHint:"À la fin du déjeuner",placeHint:"À ma table de cuisine",obstacleHint:"Un détail demandé dans la candidature est flou",fallbackHint:"Demander au recruteur de préciser le critère",observationHint:"L’envoi et sa confirmation éventuelle"},accessibleAlternative:"Écris, dicte ou utilise tes outils habituels ; demande une aide pratique si nécessaire.",stopRule:"N’augmente pas tes dépenses et ne sacrifie ni des soins nécessaires ni l’aide indispensable à un proche pour sauver un résultat incertain."},result:{question:"As-tu fait le minimum choisi ?",observationPrompt:"Qu’as-tu fait ou produit pendant cet essai ?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Julien a retravaillé son CV sans postuler. La date limite pour cette offre adaptée est ce soir. Son CV remplit les critères ; quelqu’un pourra comparer ses versions demain.",question:"Sur quoi devrait déboucher son bilan ?",options:[{id:"manifest-5-next-application",text:"Envoyer la candidature préparée, noter l’envoi et prévoir un bilan ultérieur en attendant une éventuelle réponse.",feedback:"Les notes révèlent un prochain geste concret, déjà prêt et sous le contrôle de Julien. L’action est l’envoi. La décision de l’employeur reste inconnue jusqu’à un retour réel."},{id:"manifest-5-double-editing",text:"Demander une comparaison des deux versions du CV avant de postuler pour limiter le risque d’une formulation faible.",feedback:"Comparer pourrait révéler des problèmes, mais l’avis arriverait après l’échéance de ce soir. Julien a vérifié les critères sans manque connu. Il peut envoyer cette version adaptée et utiliser les retours pour la modifier ensuite."},{id:"manifest-5-change-direction",text:"Profiter du créneau pour envoyer plusieurs candidatures moins ciblées, puis décider quelle version du CV garder.",feedback:"Viser plus large peut ouvrir des possibilités. Ici, une candidature adaptée est déjà prête. L’envoyer teste cette correspondance. Le nombre d’envois pourra être un choix ultérieur sans remplacer cette candidature ciblée et préparée."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Laisse les faits guider la suite. Effort, préparation et résultats extérieurs racontent des choses différentes.",followUp:{questionId:"manifest-5-return",question:"Que s’est-il passé pour ta tâche ou ta demande d’information ? Qu’attends-tu encore ?",observationPrompt:"Que s’est-il passé au moment prévu ?",adjustmentPrompt:"Quel changement conviendrait à ta prochaine occasion ?"}},goDeeper:{sections:[{heading:"Suivre les faits pour décider",paragraphs:["La synthèse de Harkin et ses collègues, publiée en 2016, réunissait 138 expériences avec répartition aléatoire et 19 951 participants au total. L’analyse de l’atteinte des objectifs portait sur 18 398 participants : d = 0,40, intervalle de confiance à 95 % de 0,32 à 0,48. Une analyse de sensibilité aux petites études donnait une estimation plus basse. Interventions, objectifs et façons de noter variaient. La synthèse ne testait ni le récapitulatif ODA ni sa carte du lendemain. [M03]","Les progrès notés ou rendus publics étaient associés à des effets plus grands d’une étude à l’autre. Ces comparaisons de caractéristiques n’établissent ni la nécessité de partager publiquement, ni le bénéfice causal d’un format d’application. Garde tes détails privés si tu le préfères. Compare ce que le plan demandait au geste que tu as déclaré. Sans note, le résultat reste inconnu. Une préparation terminée, une demande sans réponse et un essai interrompu gardent chacun leur sens. Tu peux ainsi examiner ta prochaine décision sans devoir raconter une réussite."]},{heading:"Choisis la semaine prochaine sans réécrire celle-ci",paragraphs:["Un carnet personnel court peut suggérer une tendance sans prouver pourquoi un résultat extérieur est arrivé. Candidatures, commandes et réponses d’autrui peuvent dépendre de la qualité, du moment, des moyens ou de circonstances absentes de tes notes. Les recherches sur le suivi soutiennent l’utilisation des informations ; elles ne fixent pas un nombre universel d’essais avant de changer d’objectif. [M03] Ton bilan doit garder cette incertitude visible.","Choisis une prochaine occasion réalisable et un moment de bilan pour la semaine à venir. Garde ton minimum utile et ce qui facilitait l’accès ; change la partie que les faits remettent en question. Sans essai noté, rapporte les faits connus ou considère le prochain petit geste comme ton premier test. N’invente pas une histoire d’efforts. Les études sur les plans trouvent des bénéfices moyens variables, sans résultat garanti. [M01] Faire une pause, demander un avis, chercher une aide pratique ou changer de direction peut résulter d’un choix réfléchi. Conserve les anciennes notes pour garder la raison de ce choix."]}],sourceIds:["M03","M01"]}},...a],d={id:"manifest",lang:"fr",title:"Ton rêve piétine ? Passe à l’action",subtitle:"Cinq leçons pour poser les bases, puis 15 techniques populaires, des preuves nuancées et une action utile.",description:"Fais avancer un souhait choisi par un travail utile. Poursuis le même essai dans la bibliothèque : découvre les rituels, examine la recherche et tente une action réalisable.",scope:"Dans ce cours, la « manifestation » désigne un travail d’intention, de préparation et d’action. Le cours ne prétend pas que les pensées dirigent les événements par des effets quantiques, que l’univers livre ce sur quoi tu te concentres ou qu’un souhait se réalisera à coup sûr. Ce ne sont pas des conseils financiers, médicaux ou psychologiques.",outcome:"Un objectif qui compte, un minimum utilisable, des notes fidèles aux essais et un plan réalisable pour la semaine suivante.",lessonLibrary:{id:"manifest-technique-library",title:"Bibliothèque de techniques",description:"15 rituels connus. Leurs étapes, ce que la recherche étaye et une version ODA avec action et bilan.",lessonIds:a.map(e=>e.id),sourceIds:s.map(e=>e.id)},photo:{id:"1676782778930-11b311ec5134",alt:"Chemin de terre montant une colline herbeuse vers des montagnes lointaines"},lessons:[{id:"manifest-1",v2:i[0],photo:{id:"1768055104910-8c8d213835fb",alt:"Main écrivant une liste de tâches dans un carnet"},schemaVersion:2,title:"Ton rêve attend encore ? Fais quelque chose d’utile",minutes:6,goal:"Produis un travail utilisable pour l’objectif que tu choisis.",reading:["Trouver un meilleur emploi, c’est un résultat. Améliorer une ligne de ton CV, c’est une action. D’autres décident de te rappeler ou non. Choisis un travail utile sans mesurer ton effort à leur réponse.","Dans une étude auprès d’étudiants, choisir où et quand commencer a favorisé le respect du délai parmi ceux qui ont rendu leur compte rendu. Cela n’a pas augmenté la participation globale. Un plan peut aider à démarrer ; il ne garantit pas le résultat. Aujourd’hui, écris une ligne, une réponse ou une demande utile. Garde cet objectif dans le cours ; rapporte les faits."],practice:["Écris ou formule mentalement un souhait qui compte pour toi, en une phrase.","Choisis une action sous ton contrôle qui te rapproche de ce souhait.","Précise une petite limite à atteindre, par exemple « trois lignes d’un premier jet »."],reflection:"Quel geste traduit ton souhait aujourd’hui ?",question:"Quelle action peux-tu choisir directement ?",options:["L’employeur me choisit à coup sûr.","Modifier trois lignes de mon CV demain.","Absolument rien ne va de travers."],correct:1,feedback:"Tu ne peux pas garantir les décisions d’autrui. Tu peux rendre ta propre préparation concrète.",takeaway:"Fais avancer ton souhait par un geste utile. Note ce geste séparément de la réponse espérée.",sources:["M10","M01","M07"],deeper:[{heading:"Ce qu’un plan pour commencer peut aider à faire",paragraphs:["En 1997, Gollwitzer et Brandstätter ont confié un compte rendu sur Noël à 86 étudiants munichois. Ceux qui planifiaient choisissaient où et quand commencer, imaginaient cette occasion, s’engageaient à démarrer et notaient leurs choix. Parmi les 36 auteurs de textes identifiables, 12/17 avec un plan et 6/19 témoins ont écrit sous les deux jours demandés. Ces proportions concernent les étudiants ayant rendu un texte identifiable, pas toutes les personnes recrutées. Le plan n’a pas augmenté la participation globale. [M10]","Choisis une occasion précise pour réaliser un travail utile. Cette adaptation n’a pas été testée dans l’étude du compte rendu de Noël. Une date ne dit pas d’où viendra le temps disponible. Choisis un événement reconnaissable et un lieu accessible. Si les moyens manquent, les demander peut être ton geste concret. Note alors une demande, même si l’aide n’est pas encore arrivée."]},{heading:"Un souhait ne décide pas pour les autres",paragraphs:["La synthèse de Wang (2021) réunissait 24 effets indépendants issus de 21 articles, avec 15 907 participants. Associer résultat souhaité, obstacle et réponse « si… alors… » montrait un bénéfice moyen modeste pour atteindre les objectifs : g = 0,336, intervalle de confiance à 95 % de 0,229 à 0,443. Les résultats variaient beaucoup et une correction du biais de publication réduisait l’estimation. Cela soutient une planification réaliste, sans promesse pour ce cours. [M01]","Dixon et ses collègues ont étudié la croyance en la manifestation dans trois enquêtes américaines en ligne totalisant 1 023 participants. Cette croyance était corrélée à certains risques financiers déclarés et aux faillites déclarées, mais pas au revenu ni au niveau d’études déclarés. Ces liens ne montrent pas que la croyance cause la faillite et ne testent pas objectivement chaque exercice de manifestation. [M07] Utilise ton souhait pour choisir un travail et évaluer les contraintes. N’en conclus pas que tes pensées ont attiré une occasion, causé tes difficultés ou rendu un résultat mérité. L’argent, les soins à recevoir ou à apporter, l’accès aux ressources et les décisions d’autrui comptent toujours."]}],example:{title:"Julien se lance",text:"Après dîner, à la table de la cuisine, Julien consacre dix minutes à sa recherche d’emploi en logistique. Il réécrit une ligne sur huit créneaux planifiés à l’entrepôt. La formulation reste maladroite. Il l’enregistre et note la modification. Aucun employeur ne l’a vue. Demain, il pourra améliorer ce premier jet."}},{id:"manifest-2",v2:i[1],photo:{id:"1517363898874-737b62a7db91",alt:"Personne assise au calme près d’une fenêtre dans une lumière chaude"},schemaVersion:2,title:"Encore en train de répéter ? Termine par un geste",minutes:6,goal:"Répète mentalement un point difficile, puis fais la prochaine partie utile de ta tâche.",reading:["Reprends ta tâche et tes notes. Répéter mentalement, c’est imaginer un geste précis, comme prononcer la première phrase. Lister les étapes est une autre préparation. Aucune des deux ne constitue l’essai réel.","Une synthèse a trouvé des bénéfices moyens de la simulation mentale sur le comportement, sans établir quel type serait le meilleur. Elle ne valide pas cette courte répétition. Utilise-la pour repérer un blocage et une réponse possible. Si les images ne viennent pas, décris le geste avec des mots. Puis écris la prochaine ligne utile de la même tâche."],practice:["Précise un changement que cet objectif apporterait à ta vie.","Mets tes deux premiers gestes dans l’ordre, en images ou avec des mots.","Après la répétition mentale, fais réellement une étape de préparation."],reflection:"Quelle préparation manquante as-tu repérée en répétant ?",question:"Que signifie répéter mentalement dans ce cours ?",options:["Faire un exercice qui prépare une action réelle.","Contrôler à coup sûr les événements par ses pensées.","Ne plus avoir besoin d’essayer."],correct:0,feedback:"Répéter, c’est préparer. Les études citées ne valident pas cet exercice court précis et ne montrent pas qu’il contrôle les résultats extérieurs. Utilise la préparation pour soutenir un vrai geste.",takeaway:"Termine la préparation utile par un vrai geste. Note les deux séparément.",sources:["M04","M10"],deeper:[{heading:"Ce que les recherches sur la simulation permettent de comparer",paragraphs:["La synthèse de Cole et ses collègues, publiée en 2021, réunissait 94 études, 123 effets et 5 685 participants. L’effet global de la simulation mentale sur le comportement était g = 0,49, intervalle de confiance à 95 % de 0,37 à 0,62. Les échantillons étaient surtout étudiants. Contenu, durée et résultats mesurés variaient : cette moyenne ne prédit pas l’effet de ton exercice court. [M04]","La synthèse distinguait réfléchir aux étapes et imaginer l’exécution d’une tâche. L’estimation pour les seules étapes reposait sur cinq effets, avec un intervalle de confiance incluant l’absence d’effet. La comparaison globale des types n’était pas statistiquement significative. Des moyennes plus élevées dans certains sous-groupes n’établissent donc aucun gagnant fiable. Un graphique ne t’invite pas à visualiser plus fort. Cette leçon utilise une répétition pour repérer un détail pratique, puis te propose d’essayer la tâche. La description écrite est une option d’accessibilité, sans équivalence démontrée avec les images."]},{heading:"Prépare-toi pour une occasion, puis saisis-la",paragraphs:["Dans l’expérience sur le compte rendu, les participants imaginaient un lieu et un moment précis pour commencer. La comparaison des délais concernait les auteurs identifiables de textes rendus et une tâche étudiante très précise. Elle n’établit ni un scénario mental universel, ni un avantage à répéter au lit. [M10] Ici, la préparation est utile quand elle t’aide à faire la prochaine partie de la tâche déjà liée à ton objectif.","Tu peux découvrir un mot de passe manquant, une consigne floue ou une phrase que tu ne sais pas encore expliquer. Réinitialiser un mot de passe prépare la tâche ; envoyer les informations demandées la fait avancer. Distingue les deux dans tes notes. Si planifier au coucher te tient éveillé, arrête et choisis un moment en journée. C’est une adaptation pratique du cours. La répétition courte est facultative : ni rituel validé, ni préalable obligatoire. Aucune image nette ni émotion particulière n’est requise."]}],example:{title:"Julien devant la ligne vide",text:"Julien reprend son CV après le dîner. Pendant trente secondes, il s’imagine décrire un changement de planning difficile. Il s’attend à bloquer et répète ce début : « Réorganisé huit créneaux quand… » Puis il écrit une phrase utilisable. Il enlève deux mots et note une question de relecture. La répétition n’avait pas prévu les détails nécessaires."}},{id:"manifest-3",v2:i[2],photo:{id:"1767134063671-322e6faf9206",alt:"Arbre tombé en travers d’un sentier forestier couvert de feuilles"},schemaVersion:2,title:"L’obstacle est réel. Change les conditions",minutes:6,goal:"Pars du dernier essai pour tester une réponse réalisable à l’obstacle.",reading:["Reprends l’objectif et tes notes. Pas encore essayé ? Précise un obstacle probable. « L’ordinateur partagé est pris après le dîner » permet de chercher une réponse. « Je manque de discipline » ne précise pas ce qui bloque.","Des études associant résultat souhaité, obstacle réel et réponse « si… alors… » ont trouvé des bénéfices moyens modestes. L’inconfort n’est pas un mécanisme établi. L’argent, les soins à recevoir ou l’aide à apporter, le temps et l’accès sont des contraintes, pas un défaut de croyance. Teste un changement : tâche réduite, créneau disponible ou demande d’aide précise. Une demande signifie avoir demandé, pas avoir reçu l’aide."],practice:["Précise l’obstacle le plus proche de ton objectif.","Distingue ce que tu peux changer de ce qui nécessite du soutien ou du temps.","Si ce n’est pas possible maintenant, réduis l’objectif ou reporte-le à un moment adapté."],reflection:"En regardant l’obstacle plus concrètement, qu’as-tu changé dans ton plan ?",question:"Quand les conditions extérieures bloquent…",options:["Je dois penser que je n’y ai pas assez cru.","Je dois ignorer ces conditions.","Je peux revoir l’aide nécessaire, le moment ou la taille de l’objectif."],correct:2,feedback:"Un plan réaliste tient compte des conditions extérieures. Tes pensées ne décident pas seules des résultats.",takeaway:"Précise ce qui bloque. Adapte la tâche ou demande l’aide dont tu as besoin.",sources:["M01","M11","M14"],deeper:[{heading:"Un obstacle renseigne ; l’inconfort n’est pas une recette",paragraphs:["La synthèse de 2021 sur le contraste mental avec plan a trouvé une amélioration moyenne modeste de l’atteinte des objectifs, à partir de 24 effets indépendants. La forte variation et les indices de biais de publication limitent la certitude. Elle n’a pas isolé l’inconfort comme ingrédient actif. Nommer une difficulté peut être désagréable ; l’exercice ne demande pas d’accentuer volontairement la détresse. [M01]","La procédure de 2015 d’Oettingen et ses collègues demandait aux étudiants de développer un résultat souhaité et un obstacle principal, de choisir une réponse, de former un plan reliant obstacle et action, puis d’ajouter les lieu et moment habituels. Dans l’étude 1, la comparaison prévue favorisait cette méthode pour les heures inscrites au calendrier. On mesurait la planification, pas le travail réalisé ; le test global des groupes restait non concluant. [M11] ODA ajoute une vérification pratique de faisabilité et un essai réel. Ni cette version courte, ni sa distinction entre contraintes extérieures et réponses personnelles n’ont été validées séparément."]},{heading:"Quand la bonne réponse consiste à demander de l’aide",paragraphs:["Distingue le résultat souhaité des conditions pour le poursuivre. Un outil manquant demande un accès ; une situation dangereuse, une protection ; des responsabilités envers un proche, parfois un autre créneau. C’est un choix pédagogique nourri par les recherches sur les plans, pas une classification universelle des obstacles. Une demande d’aide devient concrète quand elle précise ce dont tu as besoin et à quel moment. [M01, M11]","Sans réponse, note la demande et l’absence de retour. Ne note ni aide reçue ni tâche terminée. Tu peux choisir un autre geste possible, revoir l’objectif ou faire une pause. Face à une détresse persistante ou à des difficultés importantes au quotidien, cherche un soutien qualifié au lieu d’intensifier l’exercice. Le NIMH indique des recours aux soins et à l’aide de crise ; il ne démontre pas qu’ODA traite un trouble. [M14] Tes prochaines notes doivent décrire le geste choisi, y compris la protection ou le soutien, sans transformer l’obstacle initial en manque de croyance."]}],example:{title:"Julien change de créneau",text:"Julien voulait retravailler son CV après dîner, mais sa fille utilisait l’ordinateur partagé pour ses devoirs. Il note ce conflit. Il demande dix minutes avant dîner le lendemain. Ils se mettent d’accord. Il améliore alors une ligne puis s’arrête. La candidature nécessite encore du travail."}},{id:"manifest-4",v2:i[3],photo:{id:"1591462391971-9ffc57b382b9",alt:"Notes adhésives colorées et stylos"},schemaVersion:2,title:"N’attends plus le bon état d’esprit",minutes:6,goal:"Choisis un signal reconnaissable et une petite réponse au blocage observé.",reading:["Le signal et la réponse à un obstacle ont des rôles différents. « Après avoir débarrassé, écrire une ligne du CV » choisit le moment. « Si je bloque, décrire un changement de planning » aide pendant ce créneau.","Des recherches sur divers objectifs ont trouvé qu’un plan précis « si… alors… » favorisait en moyenne le passage à l’action. Il ne supprime pas tout effort de mémoire, toute difficulté ni les contraintes pratiques. Garde ta tâche ; réponds à l’obstacle noté, s’il existe. Choisis un signal visible et une réponse réalisable. S’il n’arrive pas, note l’absence d’occasion et choisis un autre créneau."],practice:["Décris un signe de l’obstacle avec « Si… ».","Dans la partie « alors… », écris une seule petite action.","Vérifie que le plan convient au temps et aux outils disponibles, puis répète-le une fois."],reflection:"Quelle est ta phrase « si… alors… » ?",question:"Quel plan peut réellement être essayé ?",options:["Tout finira par s’arranger.","Si je bloque en ouvrant le fichier, j’écrirai d’abord le titre.","Si j’envoie de bonnes ondes, tous les obstacles disparaîtront."],correct:1,feedback:"La deuxième option relie une situation précise à une action observable. Les recherches étudient ce type de plan concret.",takeaway:"Choisis quand commencer et quoi faire si tu bloques. Vérifie ensuite ce qui s’est passé.",sources:["M02","M10","M11"],deeper:[{heading:"Ce qu’un plan précis peut soutenir",paragraphs:["Le chapitre de Gollwitzer et Sheeran, publié en 2006, réunissait 94 tests indépendants avec 8 461 participants. L’effet moyen des plans « si… alors… » sur l’atteinte des objectifs était d = 0,65, intervalle de confiance à 95 % de 0,60 à 0,70. Tâches et procédures variaient ; ces recherches anciennes n’étaient pas systématiquement préenregistrées. Rien ne garantit donc l’efficacité de n’importe quelle phrase écrite par un apprenant. [M02]","L’expérience sur le compte rendu demandait aux étudiants de choisir où et quand commencer. La comparaison des délais concernait les auteurs de textes rendus identifiables, pas toutes les personnes auxquelles la tâche était confiée. [M10] La leçon pratique est plus limitée que « un plan remplace la volonté ». Choisis une réponse à l’avance, puis vérifie si la situation est arrivée, si tu l’as repérée et si la réponse convenait. Garde les rappels extérieurs utiles. Une note près d’un outil est une option ODA, pas une garantie démontrée de la remarquer."]},{heading:"Deux rôles dans un même essai qui se poursuit",paragraphs:["Le moment choisi pour commencer précise quand essayer la tâche. Ta réponse à l’obstacle précise quoi faire si la difficulté observée apparaît. La procédure de contraste mental étudiée reliait obstacle et réponse, puis ajoutait les lieu et moment habituels. Elle n’établissait pas que chacun a besoin de deux règles distinctes. [M11] Ce cours sépare leurs rôles pour mieux comprendre ce qui bloque ton essai en cours.","Si le créneau prévu ne se présente jamais, rien ne permet de dire que ta réponse à l’obstacle a échoué. S’il arrive sans que tu le remarques, change le signal ou le rappel. Si tu le remarques mais que la réponse est trop grande, réduis la prochaine partie utile de la tâche. Ce sont des choix à tester, pas des conclusions prouvées par un carnet personnel. Garde chaque ancien essai lié à son minimum initial. Un nouveau plan ne transforme pas un essai incomplet en travail terminé. Examine ton geste réel ; soutien, repos, pause ou nouvel objectif restent possibles."]}],example:{title:"Julien repère le signal",text:"Julien pose une note près de l’ordinateur partagé : « Après avoir débarrassé, améliorer une ligne. Si je bloque, décrire un changement de planning. » Jeudi, il débarrasse et remarque la note. Il écrit une ligne utile, mais ne termine pas la rubrique avant de reprendre ses responsabilités familiales. Il note ces faits."}},{id:"manifest-5",v2:i[4],photo:{id:"1762920738995-f393efe82205",alt:"Panneau de bois indiquant plusieurs directions dans une forêt"},schemaVersion:2,title:"Aucun résultat ? Regarde ce que tu as fait",minutes:6,goal:"Tes notes guideront une suite réalisable et le bilan de la semaine prochaine.",reading:["Relis les notes du même objectif. Sépare tes plans, tes répétitions mentales, tes actions et ce que tu as reçu d’autrui. Un premier jet enregistré montre un travail de rédaction. Il ne prouve ni l’envoi d’une candidature ni l’intérêt d’un employeur.","Une synthèse de 138 expériences trouvait des bénéfices moyens du suivi renforcé des progrès. Elle n’a validé ni ces notes précises ni un rythme idéal de bilan. Pars des faits : répéter un geste réalisable, modifier un problème, demander un avis ou arrêter un objectif inadapté. Sans essai, reconnais ce manque et fais une première partie utile."],practice:["Fais un premier petit essai ou précise exactement quand le faire.","Choisis une date raisonnable pour examiner le résultat : « Qu’ai-je essayé ? Qu’ai-je appris ? »","Choisis ce qui convient : continuer, réduire le geste, demander du soutien ou changer d’objectif."],reflection:"Quel jour feras-tu le bilan de ton plan ? Avec quelles informations ?",question:"Sans le résultat souhaité, quel bilan serait le plus utile ?",options:["Mes pensées n’étaient pas assez fortes.","Examiner mes actions et les conditions, puis choisir la suite.","Garder la même attente sans regarder les faits."],correct:1,feedback:"Comparer le plan aux faits apporte des informations nouvelles. Aucun cours ne garantit un résultat ; tu peux examiner ta part et les conditions extérieures ensemble.",takeaway:"Laisse les faits guider la suite. Effort, préparation et résultats extérieurs racontent des choses différentes.",sources:["M03","M01"],deeper:[{heading:"Suivre les faits pour décider",paragraphs:["La synthèse de Harkin et ses collègues, publiée en 2016, réunissait 138 expériences avec répartition aléatoire et 19 951 participants au total. L’analyse de l’atteinte des objectifs portait sur 18 398 participants : d = 0,40, intervalle de confiance à 95 % de 0,32 à 0,48. Une analyse de sensibilité aux petites études donnait une estimation plus basse. Interventions, objectifs et façons de noter variaient. La synthèse ne testait ni le récapitulatif ODA ni sa carte du lendemain. [M03]","Les progrès notés ou rendus publics étaient associés à des effets plus grands d’une étude à l’autre. Ces comparaisons de caractéristiques n’établissent ni la nécessité de partager publiquement, ni le bénéfice causal d’un format d’application. Garde tes détails privés si tu le préfères. Compare ce que le plan demandait au geste que tu as déclaré. Sans note, le résultat reste inconnu. Une préparation terminée, une demande sans réponse et un essai interrompu gardent chacun leur sens. Tu peux ainsi examiner ta prochaine décision sans devoir raconter une réussite."]},{heading:"Choisis la semaine prochaine sans réécrire celle-ci",paragraphs:["Un carnet personnel court peut suggérer une tendance sans prouver pourquoi un résultat extérieur est arrivé. Candidatures, commandes et réponses d’autrui peuvent dépendre de la qualité, du moment, des moyens ou de circonstances absentes de tes notes. Les recherches sur le suivi soutiennent l’utilisation des informations ; elles ne fixent pas un nombre universel d’essais avant de changer d’objectif. [M03] Ton bilan doit garder cette incertitude visible.","Choisis une prochaine occasion réalisable et un moment de bilan pour la semaine à venir. Garde ton minimum utile et ce qui facilitait l’accès ; change la partie que les faits remettent en question. Sans essai noté, rapporte les faits connus ou considère le prochain petit geste comme ton premier test. N’invente pas une histoire d’efforts. Les études sur les plans trouvent des bénéfices moyens variables, sans résultat garanti. [M01] Faire une pause, demander un avis, chercher une aide pratique ou changer de direction peut résulter d’un choix réfléchi. Conserve les anciennes notes pour garder la raison de ce choix."]}],example:{title:"Julien choisit la suite de sa semaine",text:"Julien relit trois modifications datées et un créneau d’ordinateur manqué. Son CV est plus clair, mais il n’a envoyé aucune candidature. Il choisit une offre adaptée, vérifie les critères et envoie la version préparée vendredi. Il note l’envoi et prévoit un bilan la semaine suivante. Toujours aucune réponse."}},...a.map(r)]},f=Object.freeze(Object.defineProperty({__proto__:null,COURSE:d,MANIFEST_LESSONS_V2:i,SOURCES:p},Symbol.toStringTag,{value:"Module"}));export{f as m};
